CREATE PROCEDURE O7IPAVAL
   @sPtype         nvarchar(8),
   @sProwid        nvarchar(64),
   @sPsitename     nvarchar(80) OUTPUT,
   @sPcompanyname  nvarchar(80) OUTPUT,
   @sPfromlocid    nvarchar(80) OUTPUT,
   @sPtolocid      nvarchar(255) OUTPUT,
   @sPsaddr1       nvarchar(64) OUTPUT,
   @sPsaddr2       nvarchar(64) OUTPUT,
   @sPsaddr3       nvarchar(64) OUTPUT,
   @sPscity        nvarchar(20) OUTPUT,
   @sPsstate       nvarchar(30) OUTPUT,
   @sPszip         nvarchar(10) OUTPUT,
   @sChk           nvarchar(4) OUTPUT  
AS 
SET NOCOUNT ON
	declare @nCountit					integer
	declare @nRowId						integer
begin
   set @sChk = 0

   --prevent conversion error
   if @sProwid is not null and isnumeric( @sProwid ) = 0
       begin
           set @sChk = N'1'
           return
       end

   set @nRowId = cast(convert(numeric, @sProwid) as integer)

	if @sPtype = N'PORD' 
		begin
			SELECT @sPsitename = sitename,
				@sPcompanyname = companyname,
				@sPfromlocid = from_locationid,
				@sPtolocid = to_locationid,
				@sPsaddr1 = shipto_address1,
				@sPsaddr2 = shipto_address2,
				@sPsaddr3 = shipto_address3,
				@sPscity = shipto_city,
				@sPsstate = shipto_state,
				@sPszip = shipto_zip
			FROM   r5iporderlineavail
			WHERE  orl_rowid = @nRowId
			IF @@ERROR != 0
			   SET @sChk = N'1'
		end
	ELSE
		begin
			if @sPtype = N'REQ' 
			begin
				SELECT @sPsitename = sitename,
					@sPcompanyname = companyname,
					@sPfromlocid = from_locationid,
					@sPtolocid = to_locationid,
					@sPsaddr1 = shipto_address1,
					@sPsaddr2 = shipto_address2,
					@sPsaddr3 = shipto_address3,
					@sPscity = shipto_city,
					@sPsstate = shipto_state,
					@sPszip = shipto_zip
				FROM   r5ipreqlineavail
				WHERE  rql_rowid = @nRowId
				IF @@ERROR != 0
				   SET @sChk = N'1'
				end
		end
end


