CREATE PROCEDURE O7IUDIVL
    @sInsupddel        nvarchar(4),
    @sCivlinvoice      nvarchar(45),
    @sCivlinvoiceorg   nvarchar(15),
    @nNivlinvline      numeric(8,0) OUTPUT,
    @sCivlorder        nvarchar(30),
    @sCivlorderorg     nvarchar(15),
    @nNivlordline      numeric(8,0),
    @nNivlinvqty       numeric(24,6),
    @nNivlinvvalue     numeric(24,6),
    @nNivldiscount     numeric(24,6),
    @nNivlprice        numeric(24,6),
    @nNivlexch         numeric(24,12),
    @sCivlcurr         nvarchar(3),
    @nCivlexchfromdual numeric(24,12),
    @nCivlexchtodual   numeric(24,12),
    @sChk              nvarchar(5) OUTPUT  
AS
BEGIN
SET NOCOUNT ON
declare @sCheckresult           nvarchar(4)
declare @nCountit               int
declare @sX                     nvarchar(45)
declare @nReturn				int
declare @sEntcode				nvarchar(40)
/* initialise variables */
set @sChk          = N'0'
set @sCheckresult  = N'0'
set @nCountit      = 0

/* check mandatory parameters */
IF isnull(@sInsupddel, N'XXX' ) NOT IN ( N'INS', N'UPD', N'DEL' ) 
   begin
   set @sChk = N'1'
   RETURN
   end

/* If insert or update, then call preprocedure */
IF @sInsupddel IN ( N'INS', N'UPD' )
   begin
   execute @nReturn = O7PREIVL @sInsupddel
                              ,@sCivlinvoice
                              ,@sCivlorder
                              ,@nNivlordline
                              ,@nNivlinvqty
                              ,@nNivlinvvalue
                              ,@nNivldiscount
                              ,@nNivlprice
                              ,@sCheckresult OUTPUT
                              ,@sX
                              ,@sX 
   if @@ERROR <> 0 or @nReturn <> 0
      return -1
   IF @sCheckresult <> N'0'
      begin
      set @sChk = @sCheckresult
      RETURN
      end
   end

/* If insert, then do actual insert of invoice line */
IF @sInsupddel = N'INS'
   begin
   /* First get new invoice line number */
   /* #6002 Use install parameter INCRLINO for line number step size */
   set @sEntcode = @sCivlinvoice + N'#' + @sCivlinvoiceorg
   execute @nReturn = o7newline N'INV',
                                @sEntcode,
                                N'1',
                                NULL,
                                NULL,
                                @sCheckresult,
                                @nNivlinvline
   if @@ERROR <> 0 or @nReturn <> 0
      return -1

   IF @sCheckresult <> N'0'
      set @nNivlinvline = 10
      INSERT INTO r5invoicelines
                 (ivl_invoice,
		  ivl_invoice_org,
                  ivl_invline,
                  ivl_order,
                  ivl_order_org,
                  ivl_ordline,
                  ivl_invqty,
                  ivl_invvalue,
                  ivl_discount,
                  ivl_price,
                  ivl_exch,
                  ivl_curr,
                  ivl_exchfromdual,
                  ivl_exchtodual )
          VALUES (@sCivlinvoice,
		  @sCivlinvoiceorg,
                  @nNivlinvline,
                  @sCivlorder,
                  @sCivlorderorg,
                  @nNivlordline,
                  @nNivlinvqty,
                  @nNivlinvvalue,
                  @nNivldiscount,
                  @nNivlprice,
                  @nNivlexch,
                  @sCivlcurr,
                  @nCivlexchfromdual,
                  @nCivlexchtodual)			
   end
ELSE IF @sInsupddel = N'UPD'         /* If update, then do actual update of invoice line */
   UPDATE r5invoicelines
      SET ivl_invqty       = @nNivlinvqty,
          ivl_invvalue     = @nNivlinvvalue,
          ivl_discount     = @nNivldiscount,
          ivl_price        = @nNivlprice,
          ivl_exch         = @nNivlexch,
          ivl_curr         = @sCivlcurr,
          ivl_exchfromdual = @nCivlexchfromdual,
          ivl_exchtodual   = @nCivlexchtodual
    WHERE ivl_invoice      = @sCivlinvoice
      AND ivl_invoice_org  = @sCivlinvoiceorg
      AND ivl_invline      = @nNivlinvline
ELSE                             /* If delete, then do actual delete of invoice line */
   DELETE FROM r5invoicelines
    WHERE ivl_invoice     = @sCivlinvoice
      AND ivl_invline     = @nNivlinvline
      AND ivl_invoice_org = @sCivlinvoiceorg
END


