create PROCEDURE O7LRF_LINEAR_SEARCH
          @sP_objcode           nvarchar(30),
          @sP_objorg            nvarchar(15),
          @nP_startingpoint     numeric(24,6),
          @sP_startingpoint_uom nvarchar(10),
          @nP_srange            numeric(24,6),
          @sP_srange_uom        nvarchar(10),
          @nP_sessionid         numeric(38,0)
AS 
SET NOCOUNT ON
    declare @nReturn            integer

    delete from r5templrfsearch
    where tls_sessionid = @nP_sessionid
    or tls_created < getdate() - 1

    execute @nReturn = o7lrf_linear_search_recursive @sP_objcode, @sP_objorg, @nP_startingpoint, @sP_startingpoint_uom, @nP_srange, @sP_srange_uom, @nP_sessionid, @sP_objcode, @sP_objcode,  @nP_srange, @sP_srange_uom, @sP_objorg, @sP_objorg
    if @@ERROR <> 0 or @nReturn <> 0
    	RETURN -1


