create procedure O7NEWLANGWRAPPER
  @sLanguage    nvarchar(2),
  @sLanginst    nvarchar(10),
  @sBoilertexts nvarchar(10),
  @sErrtexts    nvarchar(10),
  @sExtmenus    nvarchar(10),
  @sCodedescs   nvarchar(10),
  @dFromdate    nvarchar(10)
as
  SET NOCOUNT ON

  declare @dDate   datetime
  declare @nReturn int
  declare @sOutput nvarchar(3)

  if @dFromdate IS NOT NULL
    set @dDate = dbo.TO_DATE( @dFromdate, N'MM-DD-YYYY' )

  /* Remove the values from the job parameter table. */
  UPDATE r5jobparamvalue
  SET    jpv_value = ''
  WHERE  jpv_code  = '29'
  AND    jpv_line  > 0

  /* Make the job inactive. */
  UPDATE r5scheduledjobs
  SET    scj_active = '-'
  WHERE  scj_code = '29'


  execute @nReturn = o7newlang @sLanguage, @sLanginst, @sBoilertexts, @sErrtexts, @sExtmenus, @sCodedescs, @dDate, @sOutput OUTPUT
  if @@ERROR <> 0 or @nReturn <> 0
    return -1


