CREATE PROCEDURE O7NEWPPM
    @sVevtcode             nvarchar(30),
    @sVobject              nvarchar(30),
    @sVobjectorg           nvarchar(15),
    @sVobtype              nvarchar(4),
    @sVobrtype             nvarchar(4),
    @sVrtype               nvarchar(4),
    @sVppmmeter            nvarchar(40),
    @sVppmmeter2           nvarchar(40),
    @sVppmnested           nvarchar(20),
    @sVisstype             nvarchar(20),
    @dVcompleted           datetime,
    @nVmeterlast           numeric(18,0),
    @nVmeterlast2          numeric(18,0),
    @nVmetmax              numeric(18,0),
    @nVmetmax2             numeric(18,0),
    @sVevtfreq             nvarchar(8),
    @sVevtperioduom        nvarchar(10),
    @sVevttarget           nvarchar(30),
    @sVmeterdue            nvarchar(30),
    @sVmeterdue2           nvarchar(30),
    @sVevtmetuom           nvarchar(30),
    @sVevtmetuom2          nvarchar(30),
    @sVppm                 nvarchar(20),
    @sVproject             nvarchar(20),
    @sVmrc                 nvarchar(15),
    @sVevtprojbud          nvarchar(20),
    @sVevtpackage          nvarchar(30),--PVCS#15487
    @sVppmnestedtolmin     nvarchar(20),
    @sVppmnestedtolmax     nvarchar(20),
    @sVppmnestedtolmetmin  nvarchar(20),
    @sVppmnestedtolmetmax  nvarchar(20),
    @sVppmnestedtolmet2min nvarchar(20),
    @sVppmnestedtolmet2max nvarchar(20),
    @sChk                  nvarchar(5) OUTPUT
AS
    SET NOCOUNT ON
    declare @sCobrtype1     nvarchar(4)     /* r5events.evt_obrtype%type */
    declare @sCobtype1      nvarchar(4)     /* r5events.evt_obtype%type */
    declare @sCobject1      nvarchar(30)     /* r5events.evt_object%type */
    declare @sCobjectorg1   nvarchar(15)     /* r5events.evt_object_org%type */
    declare @sCrtype1       nvarchar(4)     /* r5events.evt_rtype%type  */
    declare @sCheckresult   nvarchar(4)
    declare @sNewcode       nvarchar(30)     /* r5events.evt_code%type */
    declare @sNewstatus     nvarchar(4)     /* r5events.evt_status%type */
    declare @sNewrstatus    nvarchar(4)     /* r5events.evt_rstatus%type */
    declare @nCountit       int
    declare @dTarget        datetime
    declare @dDue           datetime
	declare @nReturn		int

    set @sCobrtype1   = @sVobrtype
    set @sCobtype1    = @sVobtype
    set @sCobject1    = @sVobject
    set @sCobjectorg1 = @sVobjectorg
    set @sCrtype1     = @sVrtype
    set @sChk 	  = N'0'

    SELECT @sNewrstatus  = isnull( ins_desc, N'A' )
    FROM   r5install
    WHERE  ins_code = N'PPMSTAT'

    if @@ROWCOUNT <> 1
        set @sNewrstatus = N'A'

    execute @nReturn = R5O7_O7UCODE @sNewstatus OUTPUT, @sNewrstatus, N'EVST', @sCheckresult OUTPUT
    if @@ERROR <> 0 or @nReturn <> 0
		return -1

    /* If any PPMS are in the same group as this PPM, but */
    /* with a lower frequency and the status has been set */
    /* to 'B' then update these jobs.                     */
    execute @nReturn = o7upevt7 @sVobject, @sVobjectorg, @sVevtfreq, @sVevtperioduom,
             @sVppmnested, @sVppmmeter, @nVmeterlast, @nVmetmax,
             @sVppmmeter2, @nVmeterlast2, @nVmetmax2, @dVcompleted 
    if @@ERROR <> 0 or @nReturn <> 0
		return -1

    /* create new job in case of a ppm completion */
    /* only if PPM Type is not D and PPM is not a work package --PVCS#15487 */
    IF @sVisstype <> N'D' AND @sVevtpackage IS NULL
    begin
        execute @nReturn = o7crevt2 @sVevtcode, null, null, null, @sNewrstatus, @sNewcode OUTPUT, @sCheckresult OUTPUT
        if @@ERROR <> 0 or @nReturn <> 0
	    	return -1
        IF @sCheckresult <> N'0' 
		begin
	    	set @sChk = N'1'
	    	RETURN
        end
    end
    /* If no new code is there, then no new event has been created, so return. */
    IF @sNewcode IS NULL
        RETURN

    /* Check whether new job should be bypassed */
    set @nCountit = 0
    IF @sVppmnested IS NOT NULL
    begin
        execute @nReturn = o7cknest @sVppmnested,          @sVevtfreq,             @sVevtperioduom,       @sVobject,
                @sVobjectorg,          @sVobtype,              @sVevttarget,          @sVppmmeter,
                @sVevtmetuom,          @sVmeterdue,            @sVppmmeter2,          @sVevtmetuom2,
                @sVmeterdue2,          @sVppmnestedtolmin,     @sVppmnestedtolmax,    @sVppmnestedtolmetmin,
                @sVppmnestedtolmetmax, @sVppmnestedtolmet2min, @sVppmnestedtolmet2max,@nCountit OUTPUT,
                @sCheckresult OUTPUT
        if @@ERROR <> 0 or @nReturn <> 0
	    	return -1

        IF @sCheckresult <> N'0'
        begin
            set @sChk = N'2'
            RETURN
        end

        IF @nCountit > 0
			begin
				/* New job should be bypassed, so set R5 status to 'B' */
				execute @nReturn = R5O7_O7UCODE @sNewstatus OUTPUT, N'B', N'EVST', @sCheckresult OUTPUT
	    		if @@ERROR <> 0 or @nReturn <> 0
					return -1
				set @sNewrstatus = N'B'

				UPDATE r5events
				SET    evt_rstatus = N'B',
					   evt_status  = @sNewstatus
				WHERE  evt_code = @sNewcode
			end
        else
            begin
                if @nCountit < 0
                    begin
                        execute @nReturn = o7upevt8 @sNewcode
                        if @@ERROR <> 0 or @nReturn <> 0
		                    return -1
                    end
            end

    end

    /* Copy the activities of the ppm to r5activities */
    /* First retrieve target date                     */
    SELECT @dTarget = evt_target
    FROM   r5events
    WHERE  evt_code = @sNewcode

    execute @nReturn = o7cract1 @sNewcode, @sVppm, NULL, NULL, NULL, 8, @dTarget, @sNewrstatus, NULL, NULL,
             @sVproject, @sVevtprojbud, @sVmrc, @sCheckresult OUTPUT
    if @@ERROR <> 0 or @nReturn <> 0
		return -1

    IF @sCheckresult <> N'0'
    begin
		set @sChk = N'3'
		RETURN
    end

    /* Put the relevant parent object(s) in r5eventobjects for cost rollup */
    IF @sNewrstatus = N'R'
        execute @nReturn = o7creob1 @sNewcode, @sCrtype1, @sCobject1, @sCobjectorg1 , @sCobtype1 OUTPUT,
                @sCobrtype1 OUTPUT, @sCheckresult OUTPUT 
        if @@ERROR <> 0 or @nReturn <> 0
	    	return -1

    IF @sCheckresult <> N'0'
    begin
		set @sChk = N'4'
		RETURN
    end


-- ========================================

CREATE PROCEDURE O7OMOBJC_POSTQUERY     @sLang         		nvarchar(2),
			                       		@sObjorg       		nvarchar(15),
			                       		@sOrg            	nvarchar(80) OUTPUT,
			                       		@sObjclass     		nvarchar(40),
			                       		@sClass          	nvarchar(80) OUTPUT,
			                       		@sObjcategory  		nvarchar(40),
			                       		@sCategory       	nvarchar(80) OUTPUT,
			                       		@sObjlocation  		nvarchar(40),
			                       		@sLocation       	nvarchar(80) OUTPUT,
			                       		@sObjposition  		nvarchar(40),
			                       		@sPosition       	nvarchar(80) OUTPUT,
			                       		@sObjmrc       		nvarchar(40),
			                       		@sMrc            	nvarchar(80) OUTPUT,
			                       		@sObjpart      		nvarchar(40),
			                       		@sPart           	nvarchar(80) OUTPUT,
			                       		@sObjstore     		nvarchar(40),
			                       		@sStore          	nvarchar(80) OUTPUT,
			                       		@sObjstatus    		nvarchar(40),
			                       		@sStatusdesc     	nvarchar(80) OUTPUT,
			                       		@sObjprofile   		nvarchar(40),
			                       		@sProfile        	nvarchar(80) OUTPUT,
			                       		@sObjcostcode  		nvarchar(40),
			                       		@sCostcode       	nvarchar(80) OUTPUT,
			                       		@sObjmanufact  		nvarchar(40),
			                       		@sManufact       	nvarchar(80) OUTPUT,
				                        @sObjparent    		nvarchar(30),
				                        @sParent         	nvarchar(80) OUTPUT,
				                        @sParentobtype   	nvarchar(4) OUTPUT,
				                        @sObj          		nvarchar(30),
				                        @sObjprimaryuom  	nvarchar(30),
				                        @sOudtotalusage  	nvarchar(18) OUTPUT,
				                        @sObjplan        	nvarchar(6) OUTPUT  
AS
BEGIN
	SET NOCOUNT ON
	declare @nReturn int
    set @sMrc = dbo.R5O7_O7GET_DESC( @sLang, N'MRC', @sObjmrc, null, null )
    set @sStatusdesc = dbo.R5O7_O7GET_DESC( @sLang, N'UCOD', @sObjstatus, N'OBST', null )
    set @sOrg = dbo.R5O7_O7GET_DESC( @sLang, N'ORG', @sObjorg, null, null )

    IF @sObjcategory IS NOT NULL
        set @sCategory = dbo.R5O7_O7GET_DESC( @sLang, N'OBJ', @sObjcategory, N'C', null )
    Else
        set @sCategory = null

    IF @sObjclass != N'#'
        set @sClass = dbo.R5O7_O7GET_DESC( @sLang, N'CLAS', @sObjclass, N'OBJ', null )
    Else
        set @sClass = null

    IF @sObjlocation != N'#'
        set @sLocation = dbo.R5O7_O7GET_DESC( @sLang, N'OBJ',@sObjlocation, N'L', null )
    Else
        set @sLocation = null

    IF @sObjposition != N'#' 
        set @sPosition = dbo.R5O7_O7GET_DESC( @sLang, N'OBJ', @sObjposition, N'P', null )
    Else
        set @sPosition = null

    IF @sObjpart IS NOT NULL 
        set @sPart = dbo.R5O7_O7GET_DESC( @sLang, N'PART', @sObjpart, null, null )
    ELSE
        set @sPart = NULL

    IF @sObjstore IS NOT NULL
        set @sStore = dbo.R5O7_O7GET_DESC( @sLang, N'STOR', @sObjstore, null, null )
    ELSE
        set @sStore = NULL

    IF @sObjprofile IS NOT NULL
        set @sProfile  = dbo.R5O7_O7GET_DESC( @sLang, N'OBJ', @sObjprofile, null, null )
    ELSE
        set @sProfile = NULL

    IF @sObjcostcode IS NOT NULL
        set @sCostcode = dbo.R5O7_O7GET_DESC( @sLang, N'CSTC', @sObjcostcode, null, null )
    ELSE
        set @sCostcode = null

    IF @sObjmanufact IS NOT NULL
        set @sManufact = dbo.R5O7_O7GET_DESC( @sLang, N'MANU', @sObjmanufact, null, null )
    ELSE
        set @sManufact = null

    execute @nReturn = O7OMOBJC_GETPARENT  @sLang ,  @sObjparent, @sObjorg, @sParent OUTPUT, @sParentobtype OUTPUT
	if @@ERROR <> 0 or @nReturn <> 0
		return -1
    execute @nReturn = O7OMOBJC_GETUSAGE  @sObj, @sObjorg, @sObjprimaryuom, @sOudtotalusage OUTPUT
	if @@ERROR <> 0 or @nReturn <> 0
		return -1

    SELECT  @sObjplan = ppm_plan
    FROM  r5ppmobjects o, r5ppms p
    WHERE ppm_revrstatus = N'A'
    AND   ppm_code       = ppo_ppm
    AND   ppm_revision   = ppo_revision
    AND   ppo_deactive   IS NULL
    AND   ppm_plan       IS NOT NULL
    AND   ppo_object     = @sObj
    AND   ppo_object_org = @sObjorg
    GROUP BY ppm_plan

END


