CREATE PROCEDURE O7OMOBJC_POSTQUERYB2EC     @sEvent        nvarchar(30),
                         					@nLabcost      NUMERIC(30, 6) OUTPUT,
                         					@nLabhours     NUMERIC(30, 6) OUTPUT,
                         					@nMatcost      NUMERIC(30, 6) OUTPUT,
                         					@nToolcost     NUMERIC(30, 6) OUTPUT,
                         					@nTotcost      NUMERIC(30, 6) OUTPUT 
AS
	SET NOCOUNT ON

	declare @nReturn	int

    set @nLabcost = dbo.O7COST_LABOUR2 ( @sEvent )

    set @nLabhours = dbo.O7COST_HOURS2 ( @sEvent )

    set @nMatcost = dbo.O7COST_MATERIAL2 ( @sEvent )

    set @nToolcost = dbo.O7COST_TOOLS2 ( @sEvent )

	set @nTotcost  = isnull( @nMatcost, 0 ) + isnull( @nLabcost, 0 ) + isnull( @nToolcost, 0 )


