create PROCEDURE O7OSROTA
    @sParent        nvarchar(30),
    @sParentorg     nvarchar(15),
    @sChild         nvarchar(30),
    @sChildorg      nvarchar(15),
    @sStore         nvarchar(15),
    @sBin           nvarchar(15),
    @sForrepair     nvarchar(8),
    @sWithdraw      nvarchar(8),
    @sCosttochild   nvarchar(8),
    @sNewchild      nvarchar(30),
    @sNewchildorg   nvarchar(15),
    @sWoorg         nvarchar(15),
    @sStandwork     nvarchar(30),
    @sEvtparent     nvarchar(30),
    @sCreatebefore  nvarchar(8),
    @sR5user        nvarchar(255),
    @sR5usergroup   nvarchar(15),
    @sStwowo        nvarchar(30) OUTPUT,
    @sChk           nvarchar(4)  OUTPUT,
    @sSyslevel      nvarchar(30),
    @sAsmlevel      nvarchar(30),
    @sComplevel     nvarchar(30),
    @sComplocation  nvarchar(80),
    @sR5role        nvarchar(30) = '*'

AS
    SET NOCOUNT ON
    declare @sDeptsec              nvarchar(400)   -- r5install.ins_desc%TYPE;
    declare @sStoresec             nvarchar(400)   -- r5install.ins_desc%TYPE;
    declare @sMultiorg             nvarchar(400)   -- r5install.ins_desc%TYPE;
    declare @sDeforg               nvarchar(400)   -- r5install.ins_desc%TYPE;
    declare @sX                    nvarchar(100)   -- VARCHAR2( 100 );
    declare @nCnt                  int             -- NUMBER;
    declare @sChk2                 nvarchar(4)     -- VARCHAR2(  4 );
    declare @sLanguage             nvarchar(2)     -- r5users.usr_lang%TYPE;
    declare @sParenttype           nvarchar(4)     -- r5objects.obj_obtype%TYPE;
    declare @sParentrtype          nvarchar(4)     -- r5objects.obj_obrtype%TYPE;
    declare @sParentlocation       nvarchar(30)    -- r5objects.obj_location%TYPE;
    declare @sParentlocationorg    nvarchar(15)    -- r5objects.obj_location_org%TYPE;
    declare @sParentmrc            nvarchar(15)    -- r5objects.obj_mrc%TYPE;
    declare @sParentstore          nvarchar(15)    -- r5objects.obj_store%TYPE;
    declare @sParentbin            nvarchar(15)    -- r5objects.obj_bin%TYPE;
    declare @sParentlot            nvarchar(12)    -- r5objects.obj_lot%TYPE;
    declare @sParentrstatus        nvarchar(4)     -- r5objects.obj_rstatus%TYPE;
    declare @sParentcommon         nvarchar(1)     -- r5userorganization.uog_common%TYPE;
    declare @sChildtype            nvarchar(4)     -- r5objects.obj_obtype%TYPE;
    declare @sChildrtype           nvarchar(4)     -- r5objects.obj_obrtype%TYPE;
    declare @sNewchildtype         nvarchar(4)     -- r5objects.obj_obtype%TYPE;
    declare @sNewchildrtype        nvarchar(4)     -- r5objects.obj_obrtype%TYPE;
    declare @sPart                 nvarchar(30)    -- r5objects.obj_part%TYPE;
    declare @sPartorg              nvarchar(15)    -- r5objects.obj_part_org%TYPE;
    declare @sCategory             nvarchar(30)    -- r5objects.obj_category%TYPE;
    declare @sClass                nvarchar(8)     -- r5objects.obj_class%TYPE;
    declare @sLot                  nvarchar(15)    -- r5objects.obj_lot%TYPE;
    declare @sChildcommon          nvarchar(1)     -- r5userorganization.uog_common%TYPE;
    declare @dCommiss              datetime        -- DATE;
    declare @sNewstore             nvarchar(15)    -- r5objects.obj_store%TYPE;
    declare @sNewbin               nvarchar(15)    -- r5objects.obj_bin%TYPE;
    declare @sNewlot               nvarchar(12)    -- r5objects.obj_lot%TYPE;
    declare @sNewpart              nvarchar(30)    -- r5objects.obj_part%TYPE;
    declare @sNewpartorg           nvarchar(15)    -- r5objects.obj_part_org%TYPE;
    declare @sNewmrc               nvarchar(15)    -- r5objects.obj_mrc%TYPE;
    declare @sNewlocation          nvarchar(30)    -- r5objects.obj_location%TYPE;
    declare @sNewlocationorg       nvarchar(15)    -- r5objects.obj_location_org%TYPE;
    declare @sNewstoreorg          nvarchar(15)    -- r5stores.str_code%TYPE;
    declare @sStoreorg             nvarchar(15)    -- r5stores.str_code%TYPE;
    declare @sMrc                  nvarchar(15)    -- r5events.evt_mrc%TYPE;
    declare @sPerson               nvarchar(15)    -- r5events.evt_person%TYPE;
    declare @sLocation             nvarchar(30)    -- r5events.evt_location%TYPE;
    declare @sLocationorg          nvarchar(15)    -- r5events.evt_location_org%TYPE;
    declare @sEvtproject           nvarchar(20)    -- r5events.evt_project%TYPE;
    declare @sEvtprojbud           nvarchar(20)    -- r5events.evt_projbud%TYPE;
    declare @sEvtorg               nvarchar(15)    -- r5events.evt_org%TYPE;
    declare @sIssuewo              nvarchar(30)    -- r5events.evt_code%TYPE;
    declare @sIssueworeturn        nvarchar(30)    -- r5events.evt_code%TYPE;
    declare @sCostcode             nvarchar(30)    -- r5events.evt_costcode%TYPE;
    declare @sRollup               nvarchar(1)     -- r5structures.stc_rollup%TYPE;
    declare @sRolldown             nvarchar(1)     -- r5structures.stc_rolldown%TYPE;
    declare @sEquivalent           nvarchar(1)     -- r5structures.stc_equivalent%TYPE;
    declare @sDowntime             nvarchar(1)     -- r5structures.stc_downtime%TYPE;
    declare @sDstatus              nvarchar(4)     -- r5objects.obj_status%TYPE;
    declare @sParrepairable        nvarchar(1)     -- r5parts.par_repairable%TYPE;
    declare @sDstore               nvarchar(15)    -- r5stores.str_code%TYPE;

    declare @dTemp                 datetime
    declare @sToolchk              nvarchar(4)
    declare @nReturn               int

    set @sChk = N'0'
    set @sDeptsec   = dbo.o7dflt2(N'DEPTSEC')
    set @sStoresec  = dbo.o7dflt2(N'STORESEC')
    set @sMultiorg  = dbo.o7dflt2(N'MULTIORG')
    set @sDeforg    = dbo.o7dflt2(N'DEFORG')

    if @sParent is null or @sParentorg is null
        begin
            set @sChk = N'1'
            return
        end

    select @sLanguage = usr_lang
    FROM   r5users
    WHERE  usr_code = @sR5user

    if @@ROWCOUNT <> 1
        begin
            set @sChk = N'3'
            return
        end

    set @sX = null

    if not exists( SELECT 'x'
                     FROM   r5objects o, r5userorganization u
                     WHERE  o.obj_code    <> N'*'
                     AND    o.obj_notused <> N'+'
                     AND    u.uog_org      = o.obj_org
                     AND    u.uog_user     = @sR5user
                     AND    u.uog_role     = @sR5role
                     AND    o.obj_obrtype IN ( N'A', N'S', N'P' )
                     AND    o.obj_rstatus  = N'I'
                     AND    o.obj_code     = @sParent
                     AND    o.obj_org      = @sParentOrg
                     AND    ( EXISTS( SELECT 'x'
                                      FROM   r5structures s
                                      WHERE  s.stc_parent      = o.obj_code
                                      AND    s.stc_parent_org  = o.obj_org
                                      AND    s.stc_childrtype IN ( N'A', N'P' ) ) OR @sChild IS NULL )
                     AND (  @sDeptsec = N'OFF' OR
                            EXISTS ( SELECT 'x'
                                     FROM   r5departmentsecurity d
                                     WHERE  d.dse_user = @sR5user
                                     AND    d.dse_mrc  = o.obj_mrc
                                     AND    coalesce( d.dse_readonly, N'-' ) = N'-' ) ) )
        begin
            set @sChk = N'4'
            return
        end


    SELECT @sParenttype = obj_obtype,
           @sParentrtype = obj_obrtype,
           @sParentlocation = obj_location,
           @sParentlocationorg = obj_location_org,
           @sParentmrc = obj_mrc,
           @sParentstore = obj_store,
           @sParentbin = obj_bin,
           @sParentlot = coalesce( obj_lot, N'*' ),
           @sParentrstatus = obj_rstatus,
           @sParentcommon = uog_common
    FROM   r5userorganization, r5objec


