create PROCEDURE O7OSROTA_CALLO7UPOBJ3 @sInsupddel  nvarchar(8),
                                       @sRolldown   nvarchar(1),   --start parent proc parms here
                                       @sChild      nvarchar(30),
                                       @sChildorg   nvarchar(15),
                                       @sChildtype  nvarchar(4),
                                       @sParent     nvarchar(30),
                                       @sParentorg  nvarchar(15),
                                       @sParenttype nvarchar(4)
as
    SET NOCOUNT ON
    declare @sOldrolldown   nvarchar(1)   --r5structures.stc_rolldown%TYPE;
    declare @sNewrolldown   nvarchar(1)   --r5structures.stc_rolldown%TYPE;

    declare @nReturn        int
    declare @sChk           nvarchar(4)

    set @sChk = N'0'

    if @sInsupddel = N'INS'
        begin
            set @sOldrolldown = null
            set @sNewrolldown = @sRolldown
        end
    else
        begin
            set @sOldrolldown = @sRolldown
            set @sNewrolldown = null
        end

    execute @nReturn = o7upobj3 @sInsupddel, @sChildtype, @sChild, @sChildorg,
                                @sParenttype, @sParent, @sParentorg, @sOldrolldown,
                                @sNewrolldown, @sChk OUTPUT
    if @@ERROR <> 0 or @nReturn <> 0
        return -1


