create PROCEDURE O7OSROTA_INSTRANS @sCurstore       nvarchar(15),
                                   @sCurstoreorg    nvarchar(15),
                                   @sCurtype        nvarchar(5),
                                   @sCurpart        nvarchar(30),
                                   @sCurpartorg     nvarchar(15),
                                   @sObtype         nvarchar(4),
                                   @sObrtype        nvarchar(4),
                                   @sObcode         nvarchar(30),
                                   @sOborg          nvarchar(15),
                                   @sOblot          nvarchar(12),
                                   @sObbin          nvarchar(15),
                                   @sAttach         nvarchar(1),
                                   @sAttachto       nvarchar(30),
                                   @sAttachorg      nvarchar(15),
                                   @sIssuewo        nvarchar(30),  --start parent parms here
                                   @sR5user         nvarchar(255),
                                   @sForrepair      nvarchar(8)
as
    SET NOCOUNT ON

    declare @sCode          nvarchar(30)    --r5transactions.tra_code%TYPE;
    declare @sType          nvarchar(4)     --r5transactions.tra_type%TYPE := '';
    declare @sRtype         nvarchar(4)     --r5transactions.tra_rtype%TYPE := 'I';
    declare @sStatus        nvarchar(4)     --r5transactions.tra_status%TYPE := '';
    declare @sRstatus       nvarchar(4)     --r5transactions.tra_rstatus%TYPE := 'A';
    declare @sFromentity    nvarchar(4)     --r5transactions.tra_fromentity%TYPE := '';
    declare @sFromrentity   nvarchar(4)     --r5transactions.tra_fromrentity%TYPE := 'STOR';
    declare @sToentity      nvarchar(4)     --r5transactions.tra_toentity%TYPE := '';
    declare @sTorentity     nvarchar(4)     --r5transactions.tra_torentity%TYPE := 'EVNT';
    declare @sFromtype      nvarchar(4)     --r5transactions.tra_fromtype%TYPE := '*';
    declare @sFromrtype     nvarchar(4)     --r5transactions.tra_fromrtype%TYPE := '*';
    declare @sTotype        nvarchar(4)     --r5transactions.tra_totype%TYPE := '*';
    declare @sTortype       nvarchar(4)     --r5transactions.tra_tortype%TYPE := '*';
    declare @sFromcode      nvarchar(30)    --r5transactions.tra_fromcode%TYPE := curstore;
    declare @sTocode        nvarchar(30)    --r5transactions.tra_tocode%TYPE := issuewo;
    declare @sLtype         nvarchar(4)     --r5translines.trl_type%TYPE;
    declare @sLrtype        nvarchar(4)     --r5translines.trl_type%TYPE;
    declare @sLstatus       nvarchar(8)     --r5ucodes.uco_code%TYPE;
    declare @nPrice         numeric(24,6)   --r5translines.trl_price%TYPE;
    declare @nCore          numeric(24,6)   --r5translines.trl_price%TYPE;
    declare @dSys_date      datetime
    declare @sCostcode      nvarchar(30) -- r5objects.obj_costcode

    declare @nReturn        int
    declare @sChk           nvarchar(4)

    set @dSys_date = dbo.o7gttime2( @sCurstoreorg )

    set @sType          = null
    set @sRtype         = N'I'
    set @sStatus        = null
    set @sRstatus       = N'A'
    set @sFromentity    = null
    set @sFromrentity   = N'STOR'
    set @sToentity      = null
    set @sTorentity     = N'EVNT'
    set @sFromtype      = N'*'
    set @sFromrtype     = N'*'
    set @sTotype        = N'*'
    set @sTortype       = N'*'
    set @sFromcode      = @sCurstore
    set @sTocode        = @sIssuewo

    if @sCurtype = N'SCRP'
        begin
            set @sTorentity = null
        end

    execute @nReturn = r5o7_o7maxseq @sCode OUTPUT, N'TRAN', N'1', @sChk OUTPUT
    if @@ERROR <> 0 or @nReturn <> 0
        return -1

    INSERT INTO r5transactions( tra_code, tra_rtype, tra_date, tra_fromrentity, tra_fromrtype,
           tra_fromcode, tra_fromcode_org, tra_torentity, tra_tortype, tra_tocode,
           tra_tocode_org, tra_auth, tra_desc, tra_rstatus, tra_org )
    VALUES( @sCode, N'I', @dSys_date, N'STOR', N'*',
            @sCurstore, @sCurstoreorg, N'EVNT', N'*', @sIssuewo,
            @sCurstoreorg,  @sR5user, N'I', N'A', @sCurstoreorg )

    if ( coalesce( upper( @sForrepair ), N'0' ) = N'0' and @sCurtype <> N'SCRP' ) or @sCurtype = N'ISSUE'
        begin
            set @sLrtype = N'I'
            execute @nReturn = r5o7_o7ucode @sLtype OUTPUT, N'I', N'TRAN', @sChk OUTPUT
            if @@ERROR <> 0 or @nReturn <> 0
                return -1
        end
    else
        begin
            set @sLrtype = N'RR'
            execute @nReturn = r5o7_o7ucode @sLtype OUTPUT, N'RR', N'TRTP', @sChk OUTPUT
            if @@ERROR <> 0 or @nReturn <> 0
                return -1
            set @nCore = coalesce( dbo.o7gtcore2( @sCurstore, @sCurpart, @sCurpartorg,
                                                  @sCurstoreorg, null, null ), 0 )
        end

    set @nPrice = coalesce( dbo.o7getprc( @sCurstore, @sCurpart, @sCurpartorg,
                                          @sCurstoreorg, N'B', null, null ), 0 )

    SELECT @sCostcode = evt_costcode FROM r5events WHERE evt_code = @sTocode

    INSERT INTO r5translines(
          trl_trans, trl_type, trl_rtype, trl_line, trl_date, trl_event, trl_part, trl_part_org,
          trl_obtype, trl_obrtype, trl_object, trl_object_org, trl_lot, trl_bin, trl_store,
          trl_price, trl_qty, trl_io, trl_scrapqty, trl_attach, trl_attachto, trl_attachto_org,
          trl_costcode )
    VALUES( @sCode, @sLtype, @sLrtype, 10, @dSys_date, @sTocode, @sCurpart, @sCurpartorg,
            @sObtype, @sObrtype, @sObcode, @sOborg, @sOblot, @sObbin,
            @sCurstore, coalesce( @nCore, @nPrice ), CASE @sCurtype WHEN N'ISSUE' THEN 1 WHEN N'SCRP' THEN 0 ELSE -1 END, N'-1',
            CASE @sCurtype WHEN N'SCRP' THEN 1 ELSE 0 END, @sAttach, @sAttachto, @sAttachorg,
            @sCostcode )


