create procedure O7PMINVO_IVL2_GETORDDET	@sLang				nvarchar(2),
											@sOrlorder			nvarchar(30),
											@sOrlorderorg		nvarchar(15),
											@nOrlordline		int,
											@sInvsupplier		nvarchar(30),
											@sInvsupplierorg	nvarchar(15),
											@sCatpuruom			nvarchar(30)	OUTPUT,
											@sCatref			nvarchar(50)	OUTPUT,
											@sOrdcontract		nvarchar(30)	OUTPUT,
											@nOrddiscperc		int				OUTPUT, 
											@sOrlcontract		nvarchar(30)	OUTPUT,
											@nOrldiscperc		int				OUTPUT, 
											@nOrltotextra		numeric(24,6)	OUTPUT,
											@sOrlcurr			nvarchar(3)		OUTPUT,
											@nOrlexchfromdual	numeric(24,12)	OUTPUT,
											@nOrlexchtodual		numeric(24,12)	OUTPUT,
											@nOrlexch			numeric(24,12)	OUTPUT, 
											@nOrlmultiply		numeric(10,4)	OUTPUT,
											@sOrlpart			nvarchar(30)	OUTPUT, 
											@sOrlpartorg		nvarchar(15)	OUTPUT,
											@nOrlprice			numeric(24,6)	OUTPUT,
											@nOrlordqty			numeric(24,6)	OUTPUT, 
											@nOrlrecvqty		numeric(24,6)	OUTPUT,
											@nOrlinvqty			numeric(24,6)	OUTPUT,
											@nOtherinvqty		numeric(24,6)	OUTPUT,
											@nOrlrecvvalue		numeric(24,6)	OUTPUT,
											@nOrlinvvalue		numeric(24,6)	OUTPUT,
											@nOtherinvvalue		numeric(24,6)	OUTPUT,
											@sParuom			nvarchar(30)	OUTPUT,
											@sParuom2			nvarchar(30)	OUTPUT,
											@sPartdesc			nvarchar(80)	OUTPUT,
											@sOrlpuruom			nvarchar(30)	OUTPUT,
											@sOrlreq			nvarchar(30)	OUTPUT, 
											@nOrlreqline		int				OUTPUT, 
											@sOrlevent			nvarchar(30)	OUTPUT, 
											@nOrlact			int				OUTPUT, 
											@sOrltype			nvarchar(4)		OUTPUT, 
											@sOrlrtype			nvarchar(4)		OUTPUT, 
											@sOrlcostcode		nvarchar(30)	OUTPUT, 
											@sOrltax			nvarchar(20)	OUTPUT,
											@sOrltax2			nvarchar(20)	OUTPUT,
											@nScrapqty			numeric(24,6)	OUTPUT
as
	SET NOCOUNT ON
	declare @sDiscperc		nvarchar(40)
	declare @sX				nvarchar(100)
	declare @sChk			nvarchar(4)
	declare @sOrd			nvarchar(8)
	declare @sOrg			nvarchar(24)
	declare @nLine			int

	declare @nReturn		int
	declare @sReturn		nvarchar(8)

	set @sX = null

	set @sOrd = @sOrlorder
	set @sOrg = @sOrlorderorg
	set @nLine = @nOrlordline

	select  @sOrlpart = CASE SUBSTRING( o.orl_rtype, 1, 1 ) WHEN N'S' THEN o.orl_trade ELSE o.orl_part END,
			@sOrlpartorg = o.orl_part_org,
			@nOrlprice = o.orl_price,
			@sOrlcurr = o.orl_curr,
			@nOrlexchfromdual = o.orl_exchfromdual,
			@nOrlexchtodual = o.orl_exchtodual,
			@nOrlexch = o.orl_exch,
			@nOrlmultiply = o.orl_multiply,
			@sOrlpuruom = o.orl_puruom,
			@sOrlreq = o.orl_req,
			@nOrlreqline = o.orl_reqline,
			@sOrlevent = o.orl_event,
			@nOrlact = o.orl_act,
			@sOrltype = o.orl_type,
			@sOrlrtype = o.orl_rtype,
			@sOrlcostcode = o.orl_costcode,
			@nOrlordqty = o.orl_ordqty,
			@nOrlrecvqty = o.orl_recvqty,
			@nOrlinvqty = o.orl_invqty,
			@nOrlrecvvalue = o.orl_recvvalue,
			@nOrlinvvalue = o.orl_invvalue,
			@sOrltax = o.orl_tax,
			@sOrltax2 = o.orl_tax2,
			@sOrlcontract = o.orl_contract,
			@nOrldiscperc = o.orl_discperc,
			@nOrltotextra = o.orl_totextra,
			@nScrapqty = o.orl_scrapqty
	from      r5orderlines o
	where     o.orl_order     = @sOrd
	and       o.orl_order_org = @sOrg
	and       o.orl_ordline   = @nLine 

	execute @nReturn = O7PMINVO_ORL2_X5GETPART	@sLang, @sOrlpart, @sOrlpartorg, 
												@sPartdesc OUTPUT, @sParuom OUTPUT, @sParuom2 OUTPUT
	if @@ERROR <> 0 or @nReturn <> 0
		return -1

	if substring( @sOrlrtype, 1, 1 ) = N'S'
		set @sPartdesc = dbo.R5O7_O7GET_DESC( @sLang, N'TRAD', @sOrlpart, null, null )

	execute @nReturn = O7GMOREP N'CAT', 1, @sOrlpart, @sOrlpartorg, @sInvsupplier, @sInvsupplierorg, 
								@sX OUTPUT, @sX OUTPUT, @sX OUTPUT, @sCatpuruom OUTPUT, @sCatref OUTPUT, 
								@sX OUTPUT, @sX OUTPUT, @sX OUTPUT, @sChk OUTPUT
	if @@ERROR <> 0 or @nReturn <> 0
		return -1

	execute @nReturn = R5O7CONS_VALUE_OF @sReturn OUTPUT, N'MODULE', N'C'
	if @@ERROR <> 0 or @nReturn <> 0
		return -1

	if @sReturn = N'+'
		begin
			execute @nReturn = O7GMOREP N'ORD', 2, @sOrlorder, @sOrlorderorg, @sX, 
										@sX, @sX OUTPUT, @sX OUTPUT, @sX OUTPUT, 
										@sOrdcontract OUTPUT, @sX OUTPUT, @sX OUTPUT, 
										@sDiscperc OUTPUT, @sX OUTPUT, @sChk OUTPUT
			if @@ERROR <> 0 or @nReturn <> 0
				return -1

			set @nOrddiscperc = cast( @sDiscperc as int )
		end

	if @sOrlrtype = N'SF'
		SELECT @nOtherinvvalue = SUM( ivl_invvalue * CASE inv_rtype WHEN N'I' THEN 1 ELSE -1 END )
		FROM   r5invoices,
			   r5invoicelines
		WHERE  inv_code      = ivl_invoice
		AND    inv_org       = ivl_invoice_org
		AND    inv_rstatus  <> N'C'
		AND  ( inv_rtype     = N'I' OR isnull( inv_return, N'-' ) = N'+' )
		AND    ivl_order     = @sOrd
		AND    ivl_order_org = @sOrg
		AND    ivl_ordline   = @nLine
	else
		SELECT @nOtherinvqty = SUM( CASE inv_rtype WHEN N'I' THEN ivl_invqty ELSE -ivl_returnqty END )
		FROM   r5invoices,
			   r5invoicelines
		WHERE  inv_code      = ivl_invoice
		AND    inv_org       = ivl_invoice_org
		AND    inv_rstatus  <> N'C'
		AND  ( inv_rtype     = N'I' OR isnull( inv_return, N'-' ) = N'+' )
		AND    ivl_order     = @sOrd
		AND    ivl_order_org = @sOrg
		AND    ivl_ordline   = @nLine


