create procedure O7PMINVO_IVL_GETORDDET	@sInvcode			nvarchar(45),
										@sInvorg			nvarchar(15),
										@sIvlrtype			nvarchar(4),
										@nIvlinvline		int, 
										@nIvlinvqty			numeric(24,6),
										@nOrlact			int				OUTPUT, 
										@sOrlcurr			nvarchar(3)		OUTPUT, 
										@sOrlevent			nvarchar(30)	OUTPUT, 
										@nOrlexch			numeric(24,12)	OUTPUT, 
										@nOrlexchfromdual	numeric(24,12)	OUTPUT,
										@nOrlexchtodual		numeric(24,12)	OUTPUT,
										@sOrlrtype			nvarchar(4)		OUTPUT, 
										@sOrltype			nvarchar(4)		OUTPUT, 
										@sOrlorder			nvarchar(30),
										@sOrlorderorg		nvarchar(15),
										@nOrlordline		int,
										@nTimeworked		int				OUTPUT,
										@nMaxqty			numeric(24,6)	OUTPUT, 
										@nMaxprice			numeric(24,6)	OUTPUT, 
										@nOutstanding		numeric(24,6)	OUTPUT
as
	SET NOCOUNT ON
	declare @sOrd				nvarchar(30)	--r5orders.ord_code%TYPE
	declare @sOrg				nvarchar(15)	--r5orders.ord_org%TYPE
	declare @nLine				int
	declare @nOrlrecvvalue		numeric(24,6)
	declare @nIvlprice			numeric(24,6)
	declare @sIvlcurr			nvarchar(3)
	declare @nIvlexch			numeric(24,12)
	declare @nOrlprice			numeric(24,6)
	declare @nOutstanding2		numeric(24,6)
	declare @nIvlexchfromdual	numeric(24,12)
	declare @nIvlexchtodual		numeric(24,12)

	declare @nReturn			int

	set @sOrd = @sOrlorder
	set @sOrg = @sOrlorderorg
	set @nLine = @nOrlordline

	select  @nOrlact = o.orl_act,
			@sOrlevent = o.orl_event,
			@nOrlrecvvalue = o.orl_recvvalue,
			@sOrlcurr = o.orl_curr         ,
			@nOrlexchfromdual = o.orl_exchfromdual ,
			@nOrlexchtodual = o.orl_exchtodual   ,
			@nOrlexch = o.orl_exch,
			@sOrltype = o.orl_type,
			@sOrlrtype = o.orl_rtype
	from      r5orderlines o
	where     o.orl_order = @sOrd
	and       o.orl_order_org = @sOrg
	and       o.orl_ordline = @nLine

	if isnull( @sIvlrtype, @sOrlrtype ) = N'SF'
		begin
			execute @nReturn = O7PMINVO_ORL_X5MOREFIXED @sInvcode, @sInvorg, @sOrlorder, @sOrlorderorg, 
														@nOrlordline, @nOrlrecvvalue, @nOrlexch, @sOrlcurr, 
														@nMaxprice OUTPUT, @nIvlinvline, @nIvlprice OUTPUT, 
														@sIvlcurr OUTPUT, @nIvlexch OUTPUT
			if @@ERROR <> 0 or @nReturn <> 0
				return -1
		end
	else
		begin
			execute @nReturn = O7PMINVO_ORL_X5MORETM	@sInvcode, @sInvorg, @sOrlevent, @nOrlact, @sOrlorder, @sOrlorderorg, 
														@nOrlordline, @sIvlrtype, @sOrlcurr, @nOrlprice, @nOrlexch, @nTimeworked OUTPUT, 
														@nMaxqty OUTPUT, @nOutstanding OUTPUT, @nIvlinvqty, @nOutstanding2 OUTPUT, 
														@nIvlinvline, @nIvlprice OUTPUT, @sIvlcurr OUTPUT, @nIvlexch OUTPUT, 
														@nIvlexchfromdual OUTPUT, @nIvlexchtodual OUTPUT
			if @@ERROR <> 0 or @nReturn <> 0
				return -1
		end


