create procedure O7PMINVO_ORL_X5MOREFIXED	@sInvcode			nvarchar(45),
											@sInvorg			nvarchar(15),
											@sOrlorder			nvarchar(30),
											@sOrlorderorg		nvarchar(15),
											@nOrlordline		int,
											@nOrlrecvvalue		numeric(24,6),
											@nOrlexch			numeric(24,12), 
											@sOrlcurr			nvarchar(3),
											@nMaxprice			numeric(24,6)	OUTPUT,
											@nIvlinvline		int,
											@nIvlprice			numeric(24,6)	OUTPUT,
											@sIvlcurr			nvarchar(3)		OUTPUT,
											@sIvlexch			nvarchar(64)	OUTPUT
as
	SET NOCOUNT ON
	declare @sPrice		nvarchar(40)
	declare @sChk		nvarchar(4)
	declare @sX			nvarchar(100)
	declare @nFormatvar	numeric(24,6)	--r5invoicelines.ivl_price%TYPE

	declare @nReturn	int
	declare @sTemp		nvarchar(80)
	declare @sOrdline	nvarchar(64)

	set @sX = null

	set @sTemp = @sInvcode + N'#' + @sInvorg
	set @sOrdline = cast( @nOrlordline as nvarchar(64))
	execute @nReturn = O7GMOREP N'IVL', 2, @sTemp, @sOrlorder, @sOrlorderorg, @sOrdline,
								@sX OUTPUT, @sPrice OUTPUT, @sX OUTPUT, @sX OUTPUT, @sX OUTPUT,
								@sX OUTPUT, @sX OUTPUT, @sX OUTPUT, @sChk OUTPUT
	if @@ERROR <> 0 or @nReturn <> 0
		return -1

	set @nMaxprice = isnull( @nOrlrecvvalue / @nOrlexch, 0 ) - isnull( cast( @sPrice as numeric(24,6) ), 0 )

	if @nIvlinvline is null
		begin	
			set @nFormatvar = isnull( @nMaxprice, 0 ) * isnull( @nOrlexch, 1 )
			set @nIvlprice = @nFormatvar
			set @sIvlcurr = @sOrlcurr
			set @sIvlexch = cast( @nOrlexch as nvarchar(64) )
		end


