create procedure O7PMINVO_POSTQUERY	@sLang				nvarchar(2),
									@sInvcode			nvarchar(45),
									@sInvorg			nvarchar(15),
									@sInvauth			nvarchar(30),
									@sAuthoriser		nvarchar(80)	OUTPUT,
									@sInvsupplier		nvarchar(30),
									@sInvsupplierorg	nvarchar(15),
									@sSupplier			nvarchar(80)	OUTPUT,
									@sInvpaysupplier	nvarchar(30),
									@sInvpaysupplierorg	nvarchar(15),
									@sPaysupplier		nvarchar(80)	OUTPUT,
									@sInvorder			nvarchar(30),
									@sInvorderorg		nvarchar(15),
									@sOrderdesc			nvarchar(80)	OUTPUT,
									@sInvparent			nvarchar(45),
									@sInvparentorg		nvarchar(15),
									@sParentref			nvarchar(24)	OUTPUT,
									@sInvclass			nvarchar(8),
									@sInvclassorg		nvarchar(15),
									@sClass				nvarchar(80)	OUTPUT,
									@nDctotal			numeric(24,6)	OUTPUT,
									@nInvexch			numeric(24,12),
									@nItemvalue			numeric(24,12)	OUTPUT,
									@nItemdiscount		numeric(24,12)	OUTPUT,
									@sOrg				nvarchar(15)	OUTPUT,
									@sGlobalorg			nvarchar(15)	OUTPUT,
									@sGlobalcurr		nvarchar(3)		OUTPUT, 
									@sInvstatus			nvarchar(4)
as
	SET NOCOUNT ON
	declare @nReturn	int
	declare @sTemp		nvarchar(128)

	if @sInvauth is not null
		set @sAuthoriser = dbo.R5O7_O7GET_DESC( @sLang, N'USER', @sInvauth, null, null )

	set @sTemp = @sInvsupplier + N'#' + @sInvsupplierorg
	set @sSupplier = dbo.R5O7_O7GET_DESC( @sLang, N'COMP', @sTemp, null, null )

	if @sInvpaysupplier is not null
		begin
			set @sTemp = @sInvpaysupplier + N'#' + @sInvpaysupplierorg
			set @sSupplier = dbo.R5O7_O7GET_DESC( @sLang, N'COMP', @sTemp, null, null )
		end

	if @sInvorder is not null
		begin
			set @sTemp = @sInvorder + N'#' + @sInvorderorg
			set @sSupplier = dbo.R5O7_O7GET_DESC( @sLang, N'PORD', @sTemp, null, null )
		end

	if @sInvparent is not null
		SELECT @sParentref = inv_ref
		FROM   r5invoices
		WHERE  inv_code = @sInvparent
		AND    inv_org  = @sInvparentorg

	if @sInvclass is not null
		begin
			set @sTemp = @sInvclass + N'#' + @sInvclassorg
			set @sSupplier = dbo.R5O7_O7GET_DESC( @sLang, N'CLAS', @sTemp, N'INV', null )
		end

	set @nDctotal = dbo.O7PMINVO_X5CALCDCTOTAL( @sInvcode, @sInvorg )

	execute @nReturn = O7PMINVO_X5CALCPURVALUE @sInvcode, @sInvorg, @nInvexch, @nItemvalue OUTPUT, @nItemdiscount OUTPUT
	if @@ERROR <> 0 or @nReturn <> 0
		return -1

	execute @nReturn = O7PMINVO_X5GETORG @sLang, @sInvorg, @sOrg OUTPUT, @sGlobalorg OUTPUT, @sGlobalcurr OUTPUT
	if @@ERROR <> 0 or @nReturn <> 0
		return -1


