create procedure O7PMINVO_POSTQUERYB2ORL2	@sLang				nvarchar(2),
											@sCatpuruom			nvarchar(30)	OUTPUT,
											@sCatref			nvarchar(50)	OUTPUT,
											@sInvcode			nvarchar(45),
											@sInvorg			nvarchar(15),
											@sInvsupplier		nvarchar(30),
											@sInvsupplierorg	nvarchar(15),
