											@sIvlcurr			nvarchar(3)		OUTPUT,
											@nIvldiscount		numeric(24,6)	OUTPUT,
											@nIvlexch			numeric(24,12)	OUTPUT,
											@nIvlexchfromdual	numeric(24,12)	OUTPUT,
											@nIvlexchtodual		numeric(24,12)	OUTPUT,
											@nIvlinvline		int,
											@nIvlinvqty			numeric(24,6),
											@nIvlinvvalue		numeric(24,6)	OUTPUT,
											@nIvlprice			numeric(24,6)	OUTPUT,
											@nMaxqty			numeric(24,6)	OUTPUT,
											@sOrdcontract		nvarchar(30)	OUTPUT,
											@nOrddiscperc		int				OUTPUT, 
											@sOrlcurr			nvarchar(3)		OUTPUT,
											@nOrlexchfromdual	numeric(24,12)	OUTPUT,
											@nOrlexchtodual		numeric(24,12)	OUTPUT,
											@nOrlexch			numeric(24,12)	OUTPUT, 
											@nOrlmultiply		numeric(10,4)	OUTPUT,
											@sOrlorder			nvarchar(30),
											@sOrlorderorg		nvarchar(15),
											@nOrlordline		int,
											@sOrlpart			nvarchar(30)	OUTPUT, 
											@sOrlpartorg		nvarchar(15)	OUTPUT,
											@nOrlprice			numeric(24,6)	OUTPUT,
											@nOrlrecvqty		numeric(24,6)	OUTPUT,
											@nOutstanding		numeric(24,6)	OUTPUT,
											@nOutstanding2		numeric(24,6)	OUTPUT,
											@sParuom			nvarchar(30)	OUTPUT,
											@sParuom2			nvarchar(30)	OUTPUT,
											@sPartdesc			nvarchar(80)	OUTPUT
as
	SET NOCOUNT ON
	declare @sDiscperc		nvarchar(40)
	declare @sX				nvarchar(100)
	declare @sChk			nvarchar(4)
	declare @sOrd			nvarchar(8)
	declare @sOrg			nvarchar(24)
	declare @nLine			int

	declare @nReturn		int
	declare @sReturn		nvarchar(8)

	set @sX = null

	set @sOrd = @sOrlorder
	set @sOrg = @sOrlorderorg
	set @nLine = @nOrlordline

	select	@sOrlpart			= o.orl_part,
   			@sOrlpartorg		= o.orl_part_org,
			@sOrlcurr			= o.orl_curr,
			@nOrlexchfromdual	= o.orl_exchfromdual ,
			@nOrlexchtodual		= o.orl_exchtodual,
			@nOrlexch			= o.orl_exch,
			@nOrlmultiply		= o.orl_multiply
	from r5orderlines o
	where o.orl_order = @sOrd
	and   o.orl_order_org = @sOrg
	and   o.orl_ordline = @nLine

	execute @nReturn = O7PMINVO_ORL_X5MOREINVLINE	@sInvcode, @sInvorg, @sOrlorder, @sOrlorderorg, @nOrlordline, 
												@nIvlexchfromdual OUTPUT, @nOrlexchfromdual, @nIvlexchtodual OUTPUT, 
												@nOrlexchtodual, @nIvlprice OUTPUT, @nIvlinvvalue OUTPUT, @nIvldiscount OUTPUT, 
												@sIvlcurr OUTPUT, @nIvlexch OUTPUT, @nIvlinvline OUTPUT, @nIvlinvqty OUTPUT
	if @@ERROR <> 0 or @nReturn <> 0
		return -1

	execute @nReturn = O7PMINVO_ORL2_X5GETPART @sLang, @sOrlpart, @sOrlpartorg, @sPartdesc OUTPUT, @sParuom OUTPUT, @sParuom2 OUTPUT
	if @@ERROR <> 0 or @nReturn <> 0
		return -1

	execute @nReturn = O7GMOREP N'CAT', 1, @sOrlpart, @sOrlpartorg, @sInvsupplier, @sInvsupplierorg, 
								@sX OUTPUT, @sX OUTPUT, @sX OUTPUT, @sCatpuruom OUTPUT, @sCatref OUTPUT, 
								@sX OUTPUT, @sX OUTPUT, @sX OUTPUT, @sChk OUTPUT
	if @@ERROR <> 0 or @nReturn <> 0
		return -1

	execute @nReturn = R5O7CONS_VALUE_OF @sReturn OUTPUT, N'MODULE', N'C'
	if @@ERROR <> 0 or @nReturn <> 0
		return -1

	if @sReturn = N'+'
		begin
			execute @nReturn = O7GMOREP	N'ORD', 2, @sOrlorder, @sOrlorderorg, @sX, @sX, @sX OUTPUT, 
										@sX OUTPUT, @sX OUTPUT, @sOrdcontract OUTPUT, @sX OUTPUT, 
										@sX OUTPUT, @sDiscperc OUTPUT, @sX OUTPUT, @sChk OUTPUT
			if @@ERROR <> 0 or @nReturn <> 0
				return -1

			set @nOrddiscperc = cast( @sDiscperc as int )
		end

	execute @nReturn = O7PMINVO_ORL2_X5MORETM	@sInvcode, @sInvorg, @sOrlorder, @sOrlorderorg, @nOrlordline,
												@nOrlrecvqty, @sOrlcurr, @nOrlprice, @nOrlexch, @nOrlmultiply, 
												@nMaxqty OUTPUT, @nOutstanding OUTPUT, @nOutstanding2 OUTPUT, 
												@nIvlinvqty, @nIvlinvline, @nIvlprice OUTPUT, @sIvlcurr OUTPUT, 
												@nIvlexch OUTPUT, @nInvqty2 OUTPUT
	if @@ERROR <> 0 or @nReturn <> 0
		return -1


