create PROCEDURE O7PREACT
   @sInspud				nvarchar(3),
   @sEvent				nvarchar(30),
   @dActstart			datetime,
   @nDuration			numeric(8),
   @sNactmrc			nvarchar(15),
   @sNacttrade			nvarchar(15),
   @sNactsupplier		nvarchar(30),
   @sNactsupplierorg	nvarchar(15),
   @nActnt				numeric(24,6),
   @nActot				numeric(24,6),
   @nActest				numeric(24,6) OUTPUT,
   @nActrem				numeric(24,6) OUTPUT,
   @nNtrate				numeric(24,6) OUTPUT,
   @nOtrate				numeric(24,6) OUTPUT,
   @sAproject			nvarchar(20) OUTPUT,
   @sAprojbud			nvarchar(20) OUTPUT,
   @sChk				nvarchar(4) OUTPUT


AS
	SET NOCOUNT ON
	declare @sEproject       nvarchar(20) --r5events.evt_project%TYPE   /* Project Code of Event         */
	declare @sEprojbud       nvarchar(20) --r5events.evt_projbud%TYPE   /* Project Budget Class of Event */
	declare @sEvtrstat       nvarchar(4) --r5events.evt_rstatus%TYPE   /* rStatus of Event              */
	declare @dEvttarget      datetime                        /* Target datetime of Event          */
	declare @nEvtdur         numeric(8)                      /* Duration of Event             */
	declare @sEvtstandwork   nvarchar(20) --r5events.evt_standwork%TYPE /* Standard workorder            */
	declare @sMpproject      nvarchar(20) --r5events.evt_mpproj%TYPE    /* MS-Project code               */
	declare @sCheckresult    nvarchar(4)
	declare @nReturn		int
	declare @nCount		int


	/* Initialize */
	   set @sChk     = N'0'
	/* Check mandatory parameters */
	if @sInspud    NOT IN( N'INS', N'UPD', N'DEL' )  OR @sEvent    IS NULL  OR @nDuration IS NULL 
		begin
			set @sChk = N'1'
			return
		end
	if @sInspud = N'INS' 
		begin
			/* W0111F - Remaining Hours = Estimated Hours */
			set @nActrem = @nActest
		end
	set @nActrem = ROUND( @nActrem, 2 )

	/* W0112B - Get Rate, Overtime Rate           */
	if @sInspud = N'INS' 
		begin


		execute @nReturn = o7boorat @nNtrate OUTPUT ,@sNactmrc, @sNacttrade, null, N'N', @dActstart, N'ZZ', @sEvent,0,0,0,0, null, @sCheckresult OUTPUT 
		if @@ERROR <> 0 or @nReturn <> 0
			return -1

		execute @nReturn = o7boorat @nOtrate OUTPUT ,@sNactmrc, @sNacttrade, null, N'O', @dActstart, N'ZZ', @sEvent,0,0,0,0, null, @sCheckresult OUTPUT 
		if @@ERROR <> 0 or @nReturn <> 0
			return -1
		end

	/* Select data from r5events for the given N'@sEvent' code  */
	select @nCount = count(*) 
	FROM    r5events   e
	WHERE   e.evt_code = @sEvent 

	if @nCount = 1 
		begin
			SELECT  @sEvtrstat = e.evt_rstatus,
				  @dEvttarget = e.evt_target,
				  @nEvtdur = e.evt_duration,
				  @sEproject = e.evt_project,
				  @sEprojbud = e.evt_projbud,
				  @sEvtstandwork = e.evt_standwork,
				  @sMpproject = e.evt_mpproj
			FROM    r5events   e
			WHERE   e.evt_code = @sEvent 
		end
	else
		begin
			set @sChk = N'6'
			return
		end

	/* W0112A - Project, Project Budget Class                */
	/*           == Events Project, Project Budget Class     */
	set @sAproject = @sEproject
	set @sAprojbud = @sEprojbud

	/* W0111M, W0131M - Event is being scheduled in MS-Project */
	/*         It is not allowed to delete/updatetime/insert   */
	/*         activities while the event is being scheduled   */
	/*         will allow update by the system. Web Service    */
	/*         will check manual update.                       */
        if COALESCE(@sMpproject,N'-') <> N'-' and @sInspud <> N'UPD'  
	   begin
              if not exists ( select 1 from r5employeeorgchange
                              where eoc_inprogress = N'+' )
                begin
		  set @sChk = N'7'
		  return
                end
	   end


