create procedure O7PREARR	@sInsupddel					nvarchar(3),
							@sOld_arr_class 			nvarchar(8)		= NULL,
							@sOld_arr_clsorg 			nvarchar(15)	= NULL,
							@sOld_arr_code 				nvarchar(12)	= NULL,
							@sOld_arr_custom_tariff 	nvarchar(1)		= NULL,
							@sOld_arr_desc 				nvarchar(80)	= NULL,
							@nOld_arr_dma_charge 		numeric(5,2)	= NULL,
							@nOld_arr_fix_charge 		numeric(5,2)	= NULL,
							@nOld_arr_hir_charge 		numeric(5,2)	= NULL,
							@nOld_arr_lab_charge 		numeric(5,2)	= NULL,
							@nOld_arr_mat_charge 		numeric(5,2)	= NULL,
							@nOld_arr_tol_charge 		numeric(5,2)	= NULL,
							@sOld_arr_mat_specific 		nvarchar(1)		= NULL,
							@nOld_arr_min_time 			numeric(4)		= NULL,
							@nOld_arr_time_roundup 		numeric(4)		= NULL,
							@sNew_arr_class 			nvarchar(8)		= NULL,
							@sNew_arr_clsorg 			nvarchar(15)	= NULL,
							@sNew_arr_code 				nvarchar(12)	= NULL,
							@sNew_arr_custom_tariff 	nvarchar(1)		= NULL,
							@sNew_arr_desc 				nvarchar(80)	= NULL,
							@nNew_arr_dma_charge 		numeric(5,2)	= NULL,
							@nNew_arr_fix_charge 		numeric(5,2)	= NULL,
							@nNew_arr_hir_charge 		numeric(5,2)	= NULL,
							@nNew_arr_lab_charge 		numeric(5,2)	= NULL,
							@nNew_arr_mat_charge 		numeric(5,2)	= NULL,
							@nNew_arr_tol_charge 		numeric(5,2)	= NULL,
							@sNew_arr_mat_specific 		nvarchar(1)		= NULL,
							@nNew_arr_min_time 			numeric(4)		= NULL,
							@nNew_arr_time_roundup 		numeric(4)		= NULL
as
	SET NOCOUNT ON
	declare @sStatent	nvarchar(4)	--r5entities.ent_rentity%TYPE
	declare @sTypeent	nvarchar(4)	--r5entities.ent_rentity%TYPE
	declare @nCount		int
	declare @sChk		nvarchar(4)
	declare @sX			nvarchar(1)
	declare @nReturn	int

	if @sInsupddel is null or @sInsupddel not in ( N'INS', N'UPD', N'DEL' )
		begin
			execute O7ERR_RAISE_ERROR N'O7PREARR', N'PROC', 1
			return -1
		end

	if @sInsupddel in ( N'INS', N'UPD' )
		begin
			if @sNew_arr_code is null
				begin
					execute O7ERR_RAISE_ERROR N'O7PREARR', N'PROC', 21
					return -1
				end
			if @sNew_arr_desc is null
				begin
					execute O7ERR_RAISE_ERROR N'O7PREARR', N'PROC', 22
					return -1
				end
		end

	if @sInsupddel = N'UPD'and @sNew_arr_code <> @sOld_arr_code
		begin
			execute O7ERR_RAISE_ERROR N'O7PREARR', N'PROC', 2
			return -1
		end

	if @sInsupddel in ( N'INS', N'UPD' )
		begin
			if @sNew_arr_class is not null
				begin
					execute @nReturn = R5O7_O7EXIST N'CLAS', N'ARR', @sNew_arr_class, @sNew_arr_clsorg, N'*', @sX, @sX, @sX, @sX, @nCount OUTPUT, @sChk OUTPUT
					if @@ERROR <> 0 or @nReturn <> 0
						return -1

					if @nCount = 0
						begin
							execute O7ERR_RAISE_ERROR N'O7PREARR', N'PROC', 5
							return -1
						end
				end

			if @nNew_arr_mat_charge < 0 or @nNew_arr_lab_charge < 0 or 
			  @nNew_arr_hir_charge < 0 or @nNew_arr_dma_charge < 0 or
			  @nNew_arr_fix_charge < 0 or @nNew_arr_tol_charge < 0
				begin
					execute O7ERR_RAISE_ERROR N'O7PREARR', N'PROC', 6
					return -1
				end

			if @nNew_arr_time_roundup < 0 or @nNew_arr_min_time < 0
				begin
					execute O7ERR_RAISE_ERROR N'O7PREARR', N'PROC', 7
					return -1
				end

			if @sNew_arr_custom_tariff = N'+' and @nNew_arr_lab_charge is not null
				begin
					execute O7ERR_RAISE_ERROR N'O7PREARR', N'PROC', 8
					return -1
				end

			if @sNew_arr_mat_specific = N'+' and @nNew_arr_mat_charge is not null
				begin
					execute O7ERR_RAISE_ERROR N'O7PREARR', N'PROC', 9
					return -1
				end
		end


