create procedure O7PREBUS
	@sInsupd		nvarchar(4),
	@sCode        	nvarchar(17),
	@sParent      	nvarchar(17),
	@sCal         	nvarchar(2),
	@nPeri          numeric(1),
	@nMrc           numeric(1),
	@nJbtp          numeric(1),
	@nCstp          numeric(1),
	@nObj           numeric(1),
	@nLoc           numeric(1),
	@nCstc			numeric(1),
	@nProj			numeric(1),
	@nToplevel      numeric(1) OUTPUT,
	@sChk           nvarchar(4) OUTPUT 
AS
SET NOCOUNT ON
	declare @sParcal				nvarchar(4)--r5calendars.cal_code%TYPE
	declare @nCountit		  		int
	declare @sX						nvarchar(4)
	declare @nReturn				int

	/* Initialize */
	set @sChk     = N'0'
	set @nCountit = 0
	set @sX       = NULL

	/* Check all mandatory parameters are supplied */
	IF @sInsupd     IS NULL OR @sCode      IS NULL OR @sCal       IS NULL OR @sInsupd     NOT IN ( N'UPD', N'INS' ) 
		begin
			set @sChk = N'1'
			return
		end

	/* U1110 - Calendar should be equal to calendar of parent */
	if @sParent IS NOT NULL  AND @sInsupd = N'INS' 
		begin
			select @nCountit = count(*) 			
			FROM   r5budgetstructure
			WHERE  bus_code = @sParent

			if @nCountit = 1 
				SELECT @sParcal = bus_cal
				FROM   r5budgetstructure
				WHERE  bus_code = @sParent
			else
				set @sParcal = null

			if @sParcal <> @sCal 
				begin
					set @sChk = N'2'
					return
				end
		end


	/* U1113 - Levels should not be the same */
	if @nPeri = @nMrc	OR 
		@nPeri = @nJbtp	OR 
		@nPeri = @nCstp OR 
		@nPeri = @nObj  OR 
		@nPeri = @nLoc  OR 
		@nPeri = @nCstc OR  
		@nPeri = @nProj OR
		@nMrc  = @nJbtp	OR  
		@nMrc  = @nCstp OR 
		@nMrc  = @nObj  OR 
		@nMrc  = @nLoc  OR 
		@nMrc  = @nCstc OR 
		@nMrc  = @nProj OR
		@nJbtp = @nCstp OR 
		@nJbtp = @nObj 	OR 
		@nJbtp = @nLoc	OR 
		@nCstp = @nObj  OR 
		@nCstp = @nLoc  OR 
		@nJbtp = @nCstc OR 
		@nJbtp = @nProj OR
		@nCstp = @nCstc OR 	
		@nCstp = @nProj OR 	
		@nObj  = @nLoc  OR 	
		@nObj  = @nCstc OR 	
		@nObj  = @nProj OR 	
		@nLoc  = @nCstc OR 	
		@nLoc  = @nProj OR 	
		@nCstc = @nProj
		begin
			set @sChk = N'3'
			return
		end


	/* U1114 - Levels should have no gaps */

	SELECT @nCountit = CASE  WHEN @nPeri IS NULL THEN 0 ELSE 1 END + 
		CASE WHEN @nMrc  IS NULL THEN 0 ELSE 1 END +
		CASE WHEN @nJbtp  IS NULL THEN 0 ELSE 1 END + 
		CASE WHEN @nCstp  IS NULL THEN 0 ELSE 1 END +
		CASE WHEN @nObj  IS NULL THEN 0 ELSE 1 END  + 
		CASE WHEN @nLoc  IS NULL THEN 0 ELSE 1 END  +
		CASE WHEN @nCstc IS NULL THEN 0 ELSE 1 END  +
        CASE WHEN @nProj IS NULL  THEN 0 ELSE 1 END




	if coalesce( @nPeri, 0 ) >= coalesce( @nMrc, 0 ) and coalesce( @nPeri, 0 ) >= coalesce( @nJbtp, 0 ) and coalesce( @nPeri, 0 ) >= coalesce( @nCstp, 0 ) and coalesce( @nPeri, 0 ) >= coalesce( @nObj, 0 ) and coalesce( @nPeri, 0 ) >= coalesce( @nLoc,  0 ) and coalesce( @nPeri, 0 ) >= coalesce( @nCstc, 0 ) and coalesce( @nPeri, 0 ) >= coalesce( @nProj, 0 )
		set @nToplevel = coalesce( @nPeri, 0 )
	else
		begin
			if coalesce( @nMrc, 0 ) >= coalesce( @nJbtp, 0 ) and coalesce( @nMrc, 0 ) >= coalesce( @nCstp, 0 ) and coalesce( @nMrc, 0 ) >= coalesce( @nObj, 0 ) and coalesce( @nMrc, 0 ) >= coalesce( @nLoc,  0 ) and coalesce( @nMrc, 0 ) >= coalesce( @nCstc, 0 ) and coalesce( @nMrc, 0 ) >= coalesce( @nProj, 0 )
				set @nToplevel = coalesce( @nMrc, 0 )
			else
				begin
					if coalesce( @nJbtp, 0 ) >= coalesce( @nCstp, 0 ) and coalesce( @nJbtp, 0 ) >= coalesce( @nObj, 0 ) and coalesce( @nJbtp, 0 ) >= coalesce( @nLoc,  0 ) and coalesce( @nJbtp, 0 ) >= coalesce( @nCstc, 0 ) and coalesce( @nJbtp, 0 ) >= coalesce( @nProj, 0 )
						set @nToplevel = coalesce( @nJbtp, 0 )
					else
						begin
							if coalesce( @nCstp, 0 ) >= coalesce( @nObj, 0 ) and coalesce( @nCstp, 0 ) >= coalesce( @nLoc,  0 ) and coalesce( @nCstp, 0 ) >= coalesce( @nCstc, 0 ) and coalesce( @nCstp, 0 ) >= coalesce( @nProj, 0 )
								set @nToplevel = coalesce( @nCstp, 0 )
							else
								begin
								if coalesce( @nObj, 0 ) >= coalesce( @nLoc,  0 ) and coalesce( @nObj, 0 ) >= coalesce( @nCstc, 0 ) and coalesce( @nObj, 0 ) >= coalesce( @nProj, 0 )
									set @nToplevel = coalesce( @nObj, 0 )
								else
									begin
										if coalesce( @nLoc, 0 ) >= coalesce( @nCstc, 0 ) and coalesce( @nLoc, 0 ) >= coalesce( @nProj, 0 )
											set @nToplevel = coalesce( @nLoc, 0 )
										else
											begin
												if coalesce( @nCstc, 0 ) >= coalesce( @nProj, 0 )
													set @nToplevel = coalesce( @nCstc, 0 )
												else
													set @nToplevel = coalesce( @nProj, 0 )
											end
									end

								end

						end
				end
		end 



   if @nCountit < @nToplevel 
	   begin
		  set @sChk = N'4'
		  return
	   end

	/* U1115 - Parent may not have details. */
	if @sParent IS NOT NULL 
		begin
			SELECT @nCountit = count(*)
			FROM   r5budgetdetails
			WHERE  bdt_budget = @sParent
			if @nCountit > 0 
				begin
					set @sChk = N'5'
					return
				end
		end

	/* U1112 - No loop in budget structure. */
	if @sParent IS NOT NULL AND @sInsupd = N'INS'
		begin 
			if @sCode = @sParent 
				begin
					set @sChk = N'6'
					return
				end
			execute @nReturn = o7existu N'BSTR', N'1', @sCode, @sParent, @sX, @sX, @sX, @sX, @nCountit OUTPUT, @sChk OUTPUT
			if @@ERROR <> 0 or @nReturn <> 0
				return -1

			if @nCountit > 0 
				begin
					set @sChk = N'6'
					return
				end
		end


