CREATE PROCEDURE O7PRECEL
    @sInsupddel     	nvarchar(10),
    @nOld_cel_cost 		numeric(24,6) = NULL,
    @nOld_cel_calc 		numeric(24,6) = NULL,
    @nOld_cel_corr 		numeric(24,6) = NULL,
    @nOld_cel_price 	numeric(24,6) = NULL,
    @sOld_cel_event 	nvarchar(30) = NULL,
    @nOld_cel_increment numeric(24,6) = NULL,
    @nOld_cel_hours 	numeric(24,6) = NULL,
    @nOld_cel_line 		numeric(24,6) = NULL,
    @sOld_cel_octype 	nvarchar(4)  = NULL,
    @sOld_cel_part 		nvarchar(30)  = NULL,
    @sOld_cel_part_org 	nvarchar(15)  = NULL,
    @nOld_cel_qty 		numeric(24,6) = NULL,
    @sOld_cel_rtype 	nvarchar(8)= NULL,
    @nOld_cel_subact 	numeric(24,6) = NULL,
    @sOld_cel_subevent 	nvarchar(30) = NULL,
    @sOld_cel_trade 	nvarchar(15) = NULL,
    @nNew_cel_cost 		numeric(24,6) = NULL,
    @nNew_cel_calc 		numeric(24,6) = NULL,
    @nNew_cel_corr 		numeric(24,6) = NULL,
    @nNew_cel_price 	numeric(24,6) OUTPUT,
    @sNew_cel_event 	nvarchar(30) = NULL,
    @nNew_cel_increment numeric(4,0) OUTPUT,
    @nNew_cel_hours 	numeric(12,2) = NULL,
    @nNew_cel_line 		numeric(8,0)  = NULL,
    @sNew_cel_octype 	nvarchar(4)  = NULL,
    @sNew_cel_part 		nvarchar(30)  = NULL,
    @sNew_cel_part_org 	nvarchar(15)  = NULL,
    @nNew_cel_qty 		numeric(24,6) = NULL,
    @sNew_cel_rtype 	nvarchar(8) OUTPUT,
    @nNew_cel_subact 	numeric(8,0) = NULL,
    @sNew_cel_subevent 	nvarchar(30) = NULL,
    @sNew_cel_trade 	nvarchar(15) = NULL
AS
	SET NOCOUNT ON
    declare @sCrstatus nvarchar(8)		/* r5ucodes.uco_code%TYPE; */
    declare @sCtype    nvarchar(8)		/* r5ucodes.uco_code%TYPE; */
    declare @sChk      nvarchar( 4 )
	declare @nReturn	int
	declare @sKey	nvarchar(48)
BEGIN
	set @sChk  = N'0'
	/* Check for mandatory parameters */
    IF @sInsupddel IS NULL
        OR @sInsupddel NOT IN (N'INS', N'UPD', N'DEL')
	BEGIN
		execute O7ERR_RAISE_ERROR N'O7PRECEL', N'PROC', 1
		return -1
    END 
	/* If not deleting */
    IF @sInsupddel IN (N'INS', N'UPD')
	BEGIN
    /* Check mandatory fields  */
	    IF @sNew_cel_event IS NULL
		BEGIN
			execute O7ERR_RAISE_ERROR N'O7PRECEL', N'PROC', 21
			return -1
	    END
	    IF @nNew_cel_increment IS NULL
		BEGIN
			execute O7ERR_RAISE_ERROR N'O7PRECEL', N'PROC', 22
			return -1
	    END
	    IF @nNew_cel_line IS NULL
		BEGIN
			execute O7ERR_RAISE_ERROR N'O7PRECEL', N'PROC', 23
			return -1
	    END
	    IF @sNew_cel_rtype IS NULL 
		BEGIN
			execute O7ERR_RAISE_ERROR N'O7PRECEL', N'PROC', 24
			return -1
	    END
	    /* Check update not allowed */
		set @sKey = @sNew_cel_event + N'#' + cast(@nNew_cel_increment as nvarchar(40)) 
		execute @nReturn = O7CEV_MORE_CEV_RSTATUS	@sCrstatus OUTPUT,
										@sKey,
										null
		if  @@ERROR <> 0 OR @nReturn <> 0
			return -1
	    /* Material and time should not both be entered. */
	    IF @sNew_cel_trade IS NOT NULL AND
	            @sNew_cel_part IS NOT NULL
		BEGIN
			execute O7ERR_RAISE_ERROR N'O7PRECEL', N'PROC', 7
			return -1
	    END
	    /* Check type */
		execute @nReturn = R5O7_O7CKCODE @sNew_cel_rtype OUTPUT, @sCtype OUTPUT, N'CETP', @sChk OUTPUT
		if @@ERROR <> 0 or @nReturn <> 0
			return -1
	    IF @sChk <> N'0'
		BEGIN
			execute O7ERR_RAISE_ERROR N'O7PRECEL', N'PROC', 8
			return -1
	    END
	    /* Derive price */
	      set @nNew_cel_price =
	            isnull (@nNew_cel_calc, 0) +
	            isnull (@nNew_cel_corr, 0)
    END
END


