CREATE PROCEDURE O7RECALCCUSTINVDETAILS
  @invoice        NVARCHAR( 30 ),
  @invorg         NVARCHAR( 15 ),
  @invrev         NUMERIC( 8 ),
  @invline        NUMERIC( 8 )
AS
BEGIN  

  DECLARE @return          INTEGER
  DECLARE @chk             NVARCHAR( 4 )
  DECLARE @qty             NUMERIC( 24, 6 )
  DECLARE @periods         NUMERIC( 24, 6 )
  DECLARE @price           NUMERIC( 24, 6 )
  DECLARE @rollup          NUMERIC( 24, 6 )
  DECLARE @invoicerollup   NUMERIC( 24, 6 )
  DECLARE @category        NVARCHAR( 4 )
  DECLARE @subcategory     NVARCHAR( 40 )
  DECLARE @level           NVARCHAR( 4 )
  DECLARE @taxrollup       NUMERIC( 24, 6 )
  DECLARE @taxpercentage   NUMERIC( 24, 6 )
  DECLARE @exch            NUMERIC( 24, 12 )
  DECLARE @estimatedusage  NVARCHAR( 1 ) 
  DECLARE @invoiceitem     NVARCHAR( 30 )
  DECLARE @contractitem    NVARCHAR( 30 )
  DECLARE @rcode           NVARCHAR( 8 )
  DECLARE @adjpercbefore   NUMERIC( 7, 4 )
  DECLARE @adjunitprice    NUMERIC( 24, 6 )
  DECLARE @adjtransaction  NUMERIC( 24, 6 )
  DECLARE @adjpercafter    NUMERIC( 7, 4 )
  DECLARE @mincharge       NUMERIC( 24, 6 )
  DECLARE @maxcharge       NUMERIC( 24, 6 )
  DECLARE @freeupto        NUMERIC( 24, 6 )
  DECLARE @invconditional  NVARCHAR( 1 )
  DECLARE @invoiceline     NUMERIC( 8 )
  DECLARE @adjustedrollup  NUMERIC( 24, 6 )
  DECLARE @rollupline      NUMERIC( 8 )
  DECLARE @rolluptotal     NUMERIC( 24, 6 )
  DECLARE @rolluptax       NUMERIC( 24, 6 )
  DECLARE @userollup       NUMERIC( 24, 6 )
  DECLARE @actualsubcat    NVARCHAR( 4 )
  DECLARE @dummy           NVARCHAR( 1 )

  /* Retrieve details data. */
  SELECT @qty            = ISNULL( cid_adjustedqty, cid_invoiceqty ), 
         @periods        = ISNULL( cid_adjustedperiods, cid_invoiceperiods ),
         @price          = ISNULL( cid_adjustedprice, cid_invoiceprice ), 
         @rollup         = ISNULL( cid_adjustedrollup, cid_invoicerollup ),
         @invoicerollup  = cid_invoicerollup, 
         @category       = cid_category, 
         @subcategory    = cid_subcategory, 
         @level          = cid_level, 
         @taxrollup      = cid_taxrollup,
         @taxpercentage  = cid_taxpercentage, 
         @exch           = cid_exch, 
         @estimatedusage = cid_estimatedusage, 
         @invoiceitem    = cid_invoiceitem, 
         @contractitem   = cii_contractitem, 
         @rcode          = cds_rcode,
         @adjpercbefore  = ccd_adjpercbefore, 
         @adjunitprice   = ccd_adjunitprice, 
         @adjtransaction = ccd_adjtransaction, 
         @adjpercafter   = ccd_adjpercafter, 
         @mincharge      = ccd_mincharge, 
         @maxcharge      = ccd_maxcharge, 
         @freeupto       = ccd_freeupto, 
         @invconditional = ccd_invoiceconditional,
         @dummy          = '+'
  FROM   r5customerinvoicedetails 
         LEFT OUTER JOIN r5customerinvoiceitems ON cii_pk = cid_invoiceitem
         LEFT OUTER JOIN r5contractchargedefs 
           LEFT OUTER JOIN r5chargedefsequences ON cds_category    = ccd_category 
                                               AND cds_subcategory = ccd_subcategory 
                                               AND cds_level       = ccd_level         
           ON ccd_pk = cid_contractchargedef  
  WHERE  cid_invoice           = @invoice
  AND    cid_invoice_org       = @invorg
  AND    cid_invoice_revision  = @invrev
  AND    cid_invoiceline       = @invline

  /* Return if no data found. */
  IF @dummy IS NULL
    RETURN

  /* Do update of changed record itself. */
  EXECUTE @return = o7recalccustinvdetails_update
          N'NORMAL', @invoice, @invorg, @invrev, @invline, @level,
          @qty, @periods, @price, @rollup, @taxrollup, @invoicerollup,
          @invconditional, @estimatedusage,
          @adjpercbefore, @adjunitprice, @adjtransaction, @adjpercafter, 
          @freeupto, @mincharge, @maxcharge, @taxpercentage, @exch
  IF @level = N'TR'
    BEGIN
      /* Do rollup to SC level. */
      IF @category = N'USCH' AND @subcategory <> N'UCU1'
        BEGIN
          EXECUTE @return = r5o7_o7rcode @actualsubcat OUTPUT, @subcategory, N'CCUC', @chk OUTPUT
          EXECUTE @return = r5o7_o7ucode @actualsubcat OUTPUT, @actualsubcat, N'CCUC', @chk OUTPUT
        END
      ELSE IF @category = N'OTCH'
        BEGIN
          EXECUTE @return = r5o7_o7rcode @actualsubcat OUTPUT, @subcategory, N'CCOC', @chk OUTPUT
          EXECUTE @return = r5o7_o7ucode @actualsubcat OUTPUT, @actualsubcat, N'CCOC', @chk OUTPUT
        END
      ELSE
        SET @actualsubcat = @subcategory

      /* Get the SC rollup invoice line. */
      SELECT @invoiceline    = cid_invoiceline, 
             @taxpercentage  = cid_taxpercentage, 
             @exch           = cid_exch, 
             @subcategory    = cid_subcategory, 
             @adjustedrollup = cid_adjustedrollup, 
             @adjpercbefore  = ccd_adjpercbefore, 
             @adjunitprice   = ccd_adjunitprice, 
             @adjtransaction = ccd_adjtransaction, 
             @adjpercafter   = ccd_adjpercafter, 
             @mincharge      = ccd_mincharge, 
             @maxcharge      = ccd_maxcharge, 
             @freeupto       = ccd_freeupto, 
             @invconditional = ccd_invoiceconditional
      FROM   r5customerinvoicedetails LEFT OUTER JOIN r5contractchargedefs ON ccd_pk = cid_contractchargedef
      WHERE  cid_invoice           = @invoice
      AND    cid_invoice_revision  = @invrev
      AND    cid_invoice_org       = @invorg
      AND    cid_invoiceitem       = @invoiceitem
      AND    cid_category          = @category
      AND    cid_subcategory       = @actualsubcat
      AND    cid_level             = N'SC'
      IF @invoiceline IS NOT NULL
        BEGIN
          /* Retrieve rollup totals. */
          SELECT @rolluptotal = SUM( ISNULL( cid_correctedtotal, 0 ) ), 
                 @rolluptax   = SUM( ISNULL( cid_taxamount, 0 ) )
          FROM   r5customerinvoiceitems, r5customerinvoicedetails
          WHERE  cid_invoiceitem       = cii_pk
          AND    cid_invoice           = @invoice
          AND    cid_invoice_org       = @invorg
          AND    cid_invoice_revision  = @invrev
          AND    cid_category          = @category
          AND    ISNULL( cid_actualsubcategory, cid_subcategory ) = @actualsubcat
          AND    cid_level             = N'TR'
          AND    cii_contractitem      = @contractitem

          SET @userollup = ISNULL( @adjustedrollup, @rolluptotal )
          EXECUTE @return = o7recalccustinvdetails_update
                  N'ROLLUP', @invoice, @invorg, @invrev, @invoiceline, N'SC',
                  NULL, NULL, NULL, @userollup, @rolluptax, @rolluptotal,
                  @invconditional, N'-',
                  @adjpercbefore, @adjunitprice, @adjtransaction, @adjpercafter, 
                  @freeupto, @mincharge, @maxcharge, @taxpercentage, @exch
        END
    END    

    IF @level IN ( N'TR', N'SC' ) 
      BEGIN
        /* Do rollup to CC level. */
        SET @actualsubcat = CASE @category
          WHEN 'SATR' THEN N'ST00'
          WHEN 'WOCH' THEN N'*'
          WHEN 'FUEL' THEN N'FC00'
          WHEN 'ENER' THEN N'EC00'
          WHEN 'USCH' THEN N'UC00'
          WHEN 'OTCH' THEN N'OT00' END   
      /* Get the SC rollup invoice line. */
      SET @invoiceline = NULL
      SELECT @invoiceline    = cid_invoiceline, 
             @taxpercentage  = cid_taxpercentage, 
             @exch           = cid_exch, 
             @subcategory    = cid_subcategory, 
             @adjustedrollup = cid_adjustedrollup, 
             @adjpercbefore  = ccd_adjpercbefore, 
             @adjunitprice   = ccd_adjunitprice, 
             @adjtransaction = ccd_adjtransaction, 
             @adjpercafter   = ccd_adjpercafter, 
             @mincharge      = ccd_mincharge, 
             @maxcharge      = ccd_maxcharge,


