CREATE PROCEDURE O7RECALCCUSTINVDETAILS_UPDATE
  @source         NVARCHAR( 10 ),
  @inv            NVARCHAR( 30 ),
  @org            NVARCHAR( 15 ),
  @rev            NUMERIC( 8 ),
  @line           NUMERIC( 8 ),
  @lev            NVARCHAR( 4 ),
  @qty            NUMERIC( 24, 6 ),   
  @periods        NUMERIC( 24, 6 ),   
  @price          NUMERIC( 24, 6 ),
  @invrollup      NUMERIC( 24, 6 ),                      
  @taxrollup      NUMERIC( 24, 6 ), 
  @origrollup     NUMERIC( 24, 6 ),
  @invcond        NVARCHAR( 1 ),
  @estimatedusage NVARCHAR( 1 ),
  @adjpercbefore  NUMERIC( 7, 4 ),
  @adjunitprice   NUMERIC( 24, 6 ),
  @adjtransaction NUMERIC( 24, 6 ),
  @adjpercafter   NUMERIC( 7, 4 ),
  @freeupto       NUMERIC( 24, 6 ),
  @mincharge      NUMERIC( 24, 6 ),
  @maxcharge      NUMERIC( 24, 6 ),
  @taxpercentage  NUMERIC( 7, 4 ),
  @exch           NUMERIC( 24, 12 ) AS
BEGIN  
  DECLARE @amount         NUMERIC( 24, 6 )
  DECLARE @adjustments    NUMERIC( 24, 6 )
  DECLARE @transtotal     NUMERIC( 24, 6 )
  DECLARE @corrtotal      NUMERIC( 24, 6 )
  DECLARE @taxbase        NUMERIC( 24, 6 )
  DECLARE @taxamount      NUMERIC( 24, 6 )
  DECLARE @invamount      NUMERIC( 24, 6 )
  DECLARE @invtaxamount   NUMERIC( 24, 6 )
  IF ISNULL( @lev, N'TR' ) = N'TR'
    SET @amount = ISNULL( @qty, 0 ) * ISNULL( @periods, 1 ) * ISNULL( @price, 0 ) 
  ELSE
    SET @amount = ISNULL( @invrollup, 0 )
  IF @invcond = N'-' OR @amount > 0
    BEGIN
      /* Calculate adjustments. */
      SET @adjustments = @amount * ISNULL( @adjpercbefore, 0 ) / 100.0                           -- Adjustment percentage before
      IF @lev = N'TR'
        SET @adjustments = @adjustments + ( ISNULL( @qty, 0 ) * ISNULL( @adjunitprice, 0 ) )
      ELSE                                                                                       -- Adjustment unit price
        SET @adjustments = @adjustments + ISNULL( @adjunitprice, 0 )                
      SET @adjustments = @adjustments + ISNULL( @adjtransaction, 0 )                             -- Adjustment transaction
      SET @adjustments = @adjustments + 
                         ( ( @amount + @adjustments ) * ISNULL( @adjpercafter, 0 ) / 100.0 )     -- Adjustment perc. after
    END
  ELSE
    SET @adjustments = 0
  SET @transtotal = @amount + ISNULL( @adjustments, 0 )
  /* calculate correction total. */
  IF ISNULL( @estimatedusage, N'-' ) = N'-'
    BEGIN
      IF @transtotal > 0
        SET @corrtotal = dbo.F_GREATEST_NUMBER( 0, @transtotal - ISNULL( @freeupto, 0 ) )             -- Apply free up to
      ELSE
        SET @corrtotal = @transtotal
      SET @corrtotal = dbo.F_GREATEST_NUMBER( @corrtotal, ISNULL( @mincharge, -999999999999999999 ) ) -- At least charge the min amt
      SET @corrtotal = dbo.F_LEAST_NUMBER( @corrtotal, ISNULL( @maxcharge, 999999999999999999 ) )     -- At most charge the max amt
    END
  ELSE
    SET @corrtotal = @transtotal
  /* Calculate tax base. */
  IF ISNULL( @lev, N'TR' ) = N'TR'
    SET @taxbase = @corrtotal
  ELSE
    SET @taxbase = @corrtotal - ISNULL( @origrollup, 0 )
  /* Calculate tax amount. */
  SET @taxamount = @taxbase * @taxpercentage / 100   
  /* Calculate totals ( using exchange rate ). */
  SET @invamount = @taxbase * ISNULL( @exch, 1 )
  SET @invtaxamount = @taxamount * ISNULL( @exch, 1 )

  /* Do actual update. */    
  UPDATE r5customerinvoicedetails
  SET    cid_transactionamount = @amount, 
         cid_adjustments       = @adjustments, 
         cid_transactiontotal  = @transtotal, 
         cid_correctedtotal    = @corrtotal, 
         cid_taxbase           = @taxbase,
         cid_taxamount         = @taxamount, 
         cid_invoiceamount     = @invamount, 
         cid_invoicetaxamount  = @invtaxamount,
         cid_invoicerollup     = CASE @source WHEN N'ROLLUP' THEN @origrollup ELSE cid_invoicerollup END,
         cid_taxrollup         = @taxrollup
  WHERE  cid_invoice           = @inv
  AND    cid_invoice_org       = @org
  AND    cid_invoice_revision  = @rev
  AND    cid_invoiceline       = @line
END


