CREATE PROCEDURE O7REPBZDLUP
  @R5_USER   NVARCHAR( 255 ),
  @R5_ORG    NVARCHAR( 15 ),
  @SEL_TABLE NVARCHAR( 256 )
AS 
BEGIN
  SET NOCOUNT ON;

  DECLARE 
    @tsql               NVARCHAR( 4000 ),
    @tabledatalake      NVARCHAR( 256 ),
    @collastsaved       NVARCHAR( 100 ),
    @lastuploaddatefmt  NVARCHAR( 100 ),
    @scheduleid         NVARCHAR( 100 );

  CREATE TABLE #r5repbzdlup_table(
    SCHEDULEID          INTEGER ,
    TABLENAME           NVARCHAR( 256 ),
    LASTUPLOADFMT       NVARCHAR( 100 ),
    UNPROCESSEDRECORDS  INTEGER,
    TOTALRECORDS        INTEGER,
    UNPROCESSEDPERCENT  NUMERIC( 28, 6 ));

  -- check if table, lastsaved column exists; set scheduleid, table, lastsaved column, last upload date
  DECLARE   tablesdatalake CURSOR LOCAL FAST_FORWARD FOR
    SELECT  table_name  tabledatalake,  
            column_name collastsaved, 
            dt.scheduleid,
            dbo.repgetfmtdatelocale( @R5_USER, @R5_ORG, dt.LASTUPDATEDAT ) lastuploaddatefmt
    FROM    information_schema.columns 
            INNER JOIN datalake_table dt
                    ON dt.name =  table_name COLLATE Latin1_General_BIN
    WHERE   column_name LIKE '%LASTSAVED'
            AND ( @SEL_TABLE = '%' OR table_name = @SEL_TABLE );

  -- loop through the cursor records and insert into temp table
  OPEN    tablesdatalake
  FETCH   NEXT FROM  tablesdatalake 
               INTO  @tabledatalake, 
                     @collastsaved, 
                     @scheduleid, 
                     @lastuploaddatefmt;
  WHILE   @@FETCH_STATUS = 0  
  BEGIN
    IF    @tabledatalake IS NOT NULL 
          AND @collastsaved IS NOT NULL 
          AND @lastuploaddatefmt IS NOT NULL 
    BEGIN
      SET @tsql = ' INSERT   INTO #r5repbzdlup_table ' +
                  ' SELECT   '  + @scheduleid + ' SCHEDULEID, ' +
                  '          ''' + @tabledatalake + ''' TABLENAME, ' +
                  '          ''' + @lastuploaddatefmt + ''' LASTUPLOADFMT, ' +
                  '          R.UNPROCESSEDRECORDS, ' +
                  '          R.TOTALRECORDS,  ' +
                  '          CASE WHEN R.TOTALRECORDS <> 0 THEN ROUND ( ( COALESCE( R.UNPROCESSEDRECORDS, 0 ) / R.TOTALRECORDS ) * 100, 2 ) ELSE 0 END UNPROCESSEDPERCENT ' +
                  ' FROM     ' +
                  '          ( SELECT  COUNT(*) TOTALRECORDS, ' +
                  '                    SUM( CASE WHEN COALESCE( ' + @collastsaved + ', GETDATE() ) >= dt.lastupdatedat THEN 1 ELSE 0 END ) UNPROCESSEDRECORDS ' +
                  '            FROM    ' + @tabledatalake +
                  '                    INNER JOIN datalake_table dt ON  name = ''' + @tabledatalake + ''' ' +
                  '            GROUP   BY dt.scheduleid  ) R ';
      EXECUTE  sp_executesql @tsql;
    END;
    FETCH    NEXT FROM  tablesdatalake 
                  INTO  @tabledatalake, 
                        @collastsaved, 
                        @scheduleid, 
                        @lastuploaddatefmt;
  END;

  CLOSE      tablesdatalake;  
  DEALLOCATE tablesdatalake; 

  -- return results
  SELECT  SCHEDULEID,
          dbo.repfmtnumlocale( @R5_USER, @R5_ORG, SCHEDULEID ) SCHEDULEIDFMT,
          TABLENAME,
          LASTUPLOADFMT,
          UNPROCESSEDRECORDS, 
          DBO.REPFMTNUMLOCALE( @R5_USER, @R5_ORG, UNPROCESSEDRECORDS ) UNPROCESSEDRECORDSFMT,
          TOTALRECORDS,
          DBO.REPFMTNUMLOCALE( @R5_USER, @R5_ORG, TOTALRECORDS ) TOTALRECORDSFMT,
          UNPROCESSEDPERCENT,
          DBO.REPFMTNUMLOCALE( @R5_USER, @R5_ORG, UNPROCESSEDPERCENT ) UNPROCESSEDPERCENTFMT,
          REPLICATE( '*', ( UNPROCESSEDPERCENT ) / 2 )  PERCENTBARA,
          REPLICATE( '*', 50 - ( UNPROCESSEDPERCENT ) / 2 ) PERCENTBARB
  FROM    #r5repbzdlup_table
  DROP    TABLE #r5repbzdlup_table;

 RETURN;
END


