    DECLARE @sSEL_PARAM7 NVARCHAR(150)
    DECLARE @sSEL_PARAM8 NVARCHAR(150)
    DECLARE @sSEL_PARAM9 NVARCHAR(150)
    DECLARE @sSEL_PARAM10 NVARCHAR(150) 
