    DECLARE @sSEL_PARAM12 NVARCHAR(150)
    DECLARE @sSEL_PARAM13 NVARCHAR(150)
    DECLARE @sSEL_PARAM14 NVARCHAR(150)
    DECLARE @sSEL_PARAM15 NVARCHAR(150)
