CREATE PROCEDURE O7REPBZSIGNDETAILS(  
    @R5_FUNC	    NVARCHAR( 6 ),	
    @R5_USER	    NVARCHAR( 255 ),
    @R5_ORG       NVARCHAR( 15 ),
    @R5_DEFORG    NVARCHAR( 15 ),
    @R5_LANG      NVARCHAR( 2 ),
    @SEL_ENT	    NVARCHAR( 4 ),
    @SEL_ENTCODE  NVARCHAR( 30 ),
    @SEL_ORG	    NVARCHAR( 15 ),
    @sCurrUser    NVARCHAR( 255 ),
    @r5role       NVARCHAR( 30 ) )    
AS
    SET NOCOUNT ON;

    DECLARE 
        @elsentity          NVARCHAR( 4 ),
        @elscode            NVARCHAR( 30 ),
        @elsentcode         NVARCHAR( 80 ),
        @elsuser            NVARCHAR( 255 ),
        @elsdate            DATETIME,
        @elssigntype        NVARCHAR( 8 ),
        @elsstatus          NVARCHAR( 4 ), 
        @elsorg             NVARCHAR( 15 ),
        @elscertifynum      NVARCHAR( 20 ),
        @elscertifytype     NVARCHAR( 8 ),
        @esvalid            INT,
        @elsuserdesc        NVARCHAR( 255 ),
        @elssigntypedesc    NVARCHAR( 255 ),
        @name               NVARCHAR( 255 ),
        @signature          NVARCHAR( 255 ),
        @erecordvalid       NVARCHAR( 1 ),
        @dateupdate         NVARCHAR( 20 ),
        @curdate            NVARCHAR( 20 ),
        @selorg             NVARCHAR( 20 ),
        @return             INT;

    CREATE TABLE #tO7REPBZSIGNRESULT ( ELS_CODE         NVARCHAR( 30 )  COLLATE Latin1_General_BIN NULL, 
                                       ELS_ENTCODE      NVARCHAR( 80 )  COLLATE Latin1_General_BIN NULL,
                                       ELS_USER         NVARCHAR( 255 ) COLLATE Latin1_General_BIN NULL,
                                       ELS_DATE         DATETIME,
                                       ELS_ENTITY       NVARCHAR( 4 )   COLLATE Latin1_General_BIN NULL,
                                       ELS_SIGNTYPE     NVARCHAR( 8 )   COLLATE Latin1_General_BIN NULL, 
                                       ELS_STATUS       NVARCHAR( 4 )   COLLATE Latin1_General_BIN NULL, 
                                       ELS_ORG          NVARCHAR( 15 )  COLLATE Latin1_General_BIN NULL,
                                       ELS_CERTIFYNUM   NVARCHAR( 20 )  COLLATE Latin1_General_BIN NULL,
                                       ELS_CERTIFYTYPE  NVARCHAR( 8 )   COLLATE Latin1_General_BIN NULL,
                                       ES_VALID         INT,
                                       ELS_USERDESC     NVARCHAR( 255 )  COLLATE Latin1_General_BIN NULL,
                                       ELS_SIGNTYPEDESC NVARCHAR( 255 )  COLLATE Latin1_General_BIN NULL,
                                       NAME             NVARCHAR( 255 )  COLLATE Latin1_General_BIN NULL,
                                       SIGNATURE        NVARCHAR( 255 )  COLLATE Latin1_General_BIN NULL,
                                       ERECORD_VALID    NVARCHAR( 1 )   COLLATE Latin1_General_BIN NULL,
                                       DATE_UPDATED     NVARCHAR( 20 )  COLLATE Latin1_General_BIN NULL,
                                       CURDATE          NVARCHAR( 20 )  COLLATE Latin1_General_BIN NULL,
                                       SEL_ORG          NVARCHAR( 20 )  COLLATE Latin1_General_BIN NULL );

    DECLARE c_bzsignresult CURSOR LOCAL FOR 
    SELECT
        ELS_ENTITY,
        ELS_CODE,
        CASE WHEN ELS_ENTITY = 'OBJ' THEN ELS_ENTCODE2 ELSE ELS_ENTCODE END ELS_ENTCODE,
        ELS_USER,
        ELS_DATE,
        ELS_SIGNTYPE,
        ELS_STATUS, 
        ELS_ORG,
        ELS_CERTIFYNUM,
        ELS_CERTIFYTYPE,
        ELS_USERDESC,
        ELS_SIGNTYPEDESC,
        COALESCE( ELS_USERDESC, DBO.REPGETDESC( @R5_LANG, 'USER', ELS_USER, NULL, NULL ) ) NAME,
        COALESCE( ELS_SIGNTYPEDESC, DBO.REPGETDESC( @R5_LANG, 'UCOD', ELS_SIGNTYPE, 'ESTP', NULL ) ) SIGNATURE,
        DBO.REPGETFMTDATILOCALE( @R5_USER, @R5_ORG, ELS_DATE ) DATE_UPDATED,
        DBO.REPGETFMTDATELOCALE( @R5_USER, @R5_ORG, DBO.REPGETSYSDATE( @R5_ORG ) ) CURDATE,
        CASE WHEN ELS_ORG = @R5_DEFORG THEN '' ELSE '[ ' + ELS_ORG + ' ]' END SEL_ORG
    FROM
        R5ELECSIGN
    WHERE
        ( els_entity = ( SELECT e.ent_rentity FROM r5entities E WHERE E.ent_entity = @SEL_ENT ) OR ( @SEL_ENT = 'EAL' AND els_entity = @SEL_ENT ) )
        AND ( ( ELS_ENTITY <> 'OBJ' AND ELS_ENTCODE = @SEL_ENTCODE )
                OR ( ELS_ENTITY = 'OBJ' AND ELS_ENTCODE2 = @SEL_ENTCODE ) )
        AND ELS_ORG LIKE  @SEL_ORG 
        AND EXISTS(SELECT 'X' FROM R5USERORGANIZATION,R5PERMISSIONS 
                   WHERE ELS_ORG = UOG_ORG 
                   AND UOG_GROUP = PRM_GROUP 
                   AND PRM_SELECT = '?' 
                   AND UOG_USER =  @R5_USER 
                   AND UOG_ROLE =  @r5role
                   AND PRM_FUNCTION =  @R5_FUNC )
        AND @R5_USER = UPPER( COALESCE( @sCurrUser, '#' ) ) ;

    OPEN c_bzsignresult;
    FETCH NEXT FROM c_bzsignresult INTO         
                    @elsentity,
                    @elscode,
                    @elsentcode,
                    @elsuser,
                    @elsdate,
                    @elssigntype,
                    @elsstatus, 
                    @elsorg,
                    @elscertifynum,
                    @elscertifytype,
                    @elsuserdesc,
                    @elssigntypedesc,
                    @name,
                    @signature,
                    @dateupdate,
                    @curdate,
                    @selorg;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXECUTE @Return = O7REPBZSIGNRESVALID @elscode, @elsentcode, @elsorg, @elsentity, @esvalid OUTPUT;
        IF @@ERROR <> 0 or @return <> 0
            BEGIN
              DROP TABLE #tO7REPBZSIGNRESULT;
              RETURN -1;
            END;

        IF  @esvalid = 0
            SET @erecordvalid = '+';
        ELSE
            SET @erecordvalid = ' ';

        INSERT INTO #tO7REPBZSIGNRESULT VALUES ( @elscode, @elsentcode, @elsuser, @elsdate, @elsentity, @elssigntype, @elsstatus, @elsorg, @elscertifynum, @elscertifytype, @esvalid, @elsuserdesc, @elssigntypedesc, @name, @signature, @erecordvalid, @dateupdate, @curdate, @selorg  );

        FETCH NEXT FROM c_bzsignresult INTO         
                        @elsentity,
                        @elscode,
                        @elsentcode,
                        @elsuser,
                        @elsdate,
                        @elssigntype,
                        @elsstatus, 
                        @elsorg,
                        @elscertifynum,
                        @elscertifytype,
                        @elsuserdesc,
                        @elssigntypedesc,
                        @name,
                        @signature,
                        @dateupdate,
                        @curdate,
                        @selorg;
    END;
    CLOSE c_bzsignresult;
    DEALLOCATE c_bzsignresult;

    SELECT * FROM #tO7REPBZSIGNRESULT;

    DROP TABLE #tO7REPBZSIGNRESULT;


